/**
 * The help page (gogreenstreets.org/help) and its questions and answers, in the
 * site's four languages. The app's Help & FAQ row opens this page. English is
 * also what the Shift assistant reads (src/lib/help/faq.tsx builds both from here),
 * so edit an answer here, in every language.
 *
 * Answers are plain text with two marks: [label](href) for a link and **bold**.
 * Screen and button names follow the app's own labels in each language.
 */
import { defineStrings } from '@/lib/site-i18n'

export const helpStrings = defineStrings(
  {
    "help.meta_title": "Help — Green Streets Initiative",
    "help.meta_description": "Everything you need to know about using Shift, unlocking rewards, running a schools challenge, or joining as a partner.",
    "help.title": "How can we help?",
    "help.intro": "Everything you need to know about using Shift, unlocking rewards, running a schools challenge, or joining as a partner.",
    "help.card_app_users": "App Users",
    "help.card_partners": "Rewards Partners",
    "help.card_schools": "Schools",
    "help.still_title": "Still need help?",
    "help.still_body": "We’re a small team and we read every message. Reach out and we’ll get back to you as quickly as we can.",
    "help.general_support": "General Support",
    "faq.getting-started.title": "Getting Started",
    "faq.getting-started.1.q": "What is Shift?",
    "faq.getting-started.1.a": "Shift is a free app from Green Streets Initiative that records your walking, biking, scooter and transit trips on its own and rewards you for them. You earn XP, badges and tiers, unlock offers at local businesses, get gift cards for trying new ways of getting around, and are entered in monthly prize drawings like Walk/Ride Day. It also shows the next buses and trains near you and plans routes.",
    "faq.getting-started.2.q": "How do I download the Shift app?",
    "faq.getting-started.2.a": "Shift is available on the App Store (iPhone) and Google Play (Android). Search for “Shift by Green Streets Initiative” or follow the download links on our [homepage](/).",
    "faq.getting-started.3.q": "How do I create an account?",
    "faq.getting-started.3.a": "Open the app and enter your email, and we’ll send you a sign-in link. You can also continue with Google, or with Apple on an iPhone. Then add your name. To appear on your town’s leaderboard, add your Home under Profile > Your places.",
    "faq.getting-started.4.q": "Is Shift really free?",
    "faq.getting-started.4.a": "Yes. Shift is completely free to download and use. There are no premium tiers, in-app purchases, or hidden fees.",
    "faq.getting-started.5.q": "What do I get for inviting friends?",
    "faq.getting-started.5.a": "Your invite code is under Profile > Invite friends. When a friend joins with your code and makes 5 trips, you get $10 to spend at a local business.",
    "faq.trip-tracking.title": "Tracking Your Trips",
    "faq.trip-tracking.1.q": "How does trip tracking work?",
    "faq.trip-tracking.1.a": "Shift uses your phone’s location in the background to notice when you walk, bike, scoot or take transit. Each trip is saved with its distance, time and mode, and shows up in your trip history. When Shift isn’t sure how you traveled, it asks you.",
    "faq.trip-tracking.2.q": "Which ways of getting around count?",
    "faq.trip-tracking.2.a": "Walking, biking, bus, subway, commuter rail, ferry, e-scooter and carpool trips earn XP. Carpools don’t count toward your tier. Driving doesn’t earn anything.",
    "faq.trip-tracking.3.q": "Shift stopped recording my trips. How do I fix it?",
    "faq.trip-tracking.3.a": "Three steps fix most cases. In your phone’s Settings, open Shift and set Location to Always (Allow all the time on Android). Turn on Motion & Fitness on an iPhone, or Physical activity on Android. Then open Shift, which starts recording again. Profile > Settings > Trip tracking shows anything else that’s off, like Precise Location or Background App Refresh, with a button to fix it, and a card at the top of Home walks you through it too. Trips under 0.1 mile or 2 minutes aren’t saved, and tunnels or underground stations can occasionally cause a missed trip.",
    "faq.trip-tracking.4.q": "I got signed out. Did I lose my trips?",
    "faq.trip-tracking.4.a": "No. While you’re signed out, Shift keeps the trips it records for up to 30 days and sends them once you sign in again.",
    "faq.trip-tracking.5.q": "Can I add a trip Shift missed?",
    "faq.trip-tracking.5.a": "Yes. Tap Log past trip on the Home tracking card, then pick how you traveled, the distance and the day, up to a week back. Trips added this way earn XP and count toward your tier, but they don’t earn drawing entries or gift-card rewards. For a trip to count for those, tap Start Trip as you set off. You can also import walks and rides from Apple Health or Health Connect in Profile > Settings > Trip tracking.",
    "faq.trip-tracking.6.q": "How do I fix a wrong travel mode?",
    "faq.trip-tracking.6.a": "Open the trip and pick the right travel mode. A trip you fix or confirm counts in full: XP, drawing entries and rewards.",
    "faq.trip-tracking.7.q": "Do trips outside Massachusetts count?",
    "faq.trip-tracking.7.a": "Shift saves them, but when a trip starts and ends outside Massachusetts, only walks earn XP and drawing entries. If you’re away for a while, you can turn on Vacation mode in Profile > Settings.",
    "faq.trip-tracking.8.q": "How accurate is background tracking?",
    "faq.trip-tracking.8.a": "Background tracking is generally accurate within a reasonable margin. GPS precision varies depending on your environment — dense urban areas with tall buildings and underground transit can reduce accuracy. The app uses intelligent filtering to distinguish modes, but occasional misclassifications can happen.",
    "faq.trip-tracking.9.q": "Does tracking drain my battery?",
    "faq.trip-tracking.9.a": "Shift uses efficient background location services designed to minimize battery impact. Most users see minimal additional drain. If you notice an issue, make sure your phone’s OS and the Shift app are both up to date.",
    "faq.getting-around.title": "Getting Around",
    "faq.getting-around.1.q": "How do I see departures near me or plan a trip?",
    "faq.getting-around.1.a": "Around You on the Home screen shows the next buses and trains near you, and nearby bikes. Tap Plan a route for directions to anywhere. You can save a trip you make often, and it shows up on Home and under Profile > Your trips.",
    "faq.getting-around.2.q": "I can ride, but traffic makes me nervous. Can I get a lesson?",
    "faq.getting-around.2.a": "Yes. If you live near Somerville, Green Streets is covering the cost of a free 1:1 street lesson with the Bicycle Riding School: 90 minutes on real streets, at your pace, one per person while lessons last. Ask for one on our [bike lessons page](/bike-lessons#street-lesson) (no app needed) or in the app, and an instructor emails you to pick a time. Farther away, or would rather wait for spring? The same page lists classes and instructors across Massachusetts and can email you when classes start again.",
    "faq.getting-around.3.q": "How does Shift Together work?",
    "faq.getting-around.3.a": "We introduce people who want to start biking or taking the T to someone nearby who already does, and they go together the first time. Sign up with where you live, where you want to go, and whether you'd like to bike or take the T. Shift suggests someone who lives within a couple of miles of you. You each see a first name, never an address. If you both say yes, you each see the other's email to plan the first trip, and Shift suggests a public place to meet. You can end a match any time with \"Something wrong?\". [Sign up](/together)",
    "faq.points-rewards.title": "XP & Rewards",
    "faq.points-rewards.1.q": "How do rewards work?",
    "faq.points-rewards.1.a": "There are two kinds. Offers at local businesses (discounts, freebies and member deals) open once you reach Mover, the second tier. You don’t spend XP on them; your tier is your key. Gift cards come from winning a drawing, finishing a challenge, trying a new way to make a regular trip, or inviting a friend.",
    "faq.points-rewards.2.q": "How do I earn XP?",
    "faq.points-rewards.2.a": "You earn XP every time you take an active trip (walk, bike, transit, carpool, or e-scooter). The amount per trip depends on your tier: Starters earn 1 XP per trip, Movers 2, Shifters 3, Pacesetters 4, and Trailblazers 5. You can earn up to 15 XP per day from trips. On top of that, you earn bonus XP for hitting badge milestones (streaks, distances, mode mix) and for tier promotions. During a Featured Goal sprint, completing the goal in time gives you a 50% XP bonus on the badge. Trips added with Log past trip earn XP too, but not drawing entries or gift-card rewards.",
    "faq.points-rewards.3.q": "Is XP a currency I can spend?",
    "faq.points-rewards.3.a": "No. XP is a record of your progress, not a wallet. It drives tier advancement and shows how far you’ve come — but you never spend it to redeem an offer. Rewards Partner offers are unlocked by your tier.",
    "faq.points-rewards.4.q": "I got a gift card. How do I use it?",
    "faq.points-rewards.4.a": "Open the Rewards tab, tap Your rewards, and pick where to spend it before the pick-by date. Brand gift cards arrive right away; cards for local shops take a couple of business days.",
    "faq.points-rewards.5.q": "How do I find and use a Rewards Partner offer?",
    "faq.points-rewards.5.a": "The Rewards tab lists every partner offer with its location and details. All of them open at Mover. To use one in a store, show your tier badge on the offer screen to the cashier. For online offers, use the code or link shown in the app.",
    "faq.points-rewards.6.q": "Where can I see my XP and tier?",
    "faq.points-rewards.6.a": "Your tier is at the top of Home; tap it for details. Your XP total and history are on the Progress tab.",
    "faq.points-rewards.7.q": "Does XP expire?",
    "faq.points-rewards.7.a": "XP is a progression metric, so there’s nothing to \"expire\" — your lifetime XP and tier history are always part of your profile. If you stop using the app for a long time we may archive inactive accounts, but as long as you’re using Shift your progress is safe.",
    "faq.points-rewards.8.q": "A Rewards Partner didn’t honor an offer I should be eligible for. What do I do?",
    "faq.points-rewards.8.a": "Email us at [info@gogreenstreets.org](mailto:info@gogreenstreets.org) with the partner name, date, and what happened. We’ll sort it out with the partner directly so you get the offer.",
    "faq.points-rewards.9.q": "Can I suggest a business as a Rewards Partner?",
    "faq.points-rewards.9.a": "Absolutely. If there’s a local business you’d love to see in the Shift network, let us know at [info@gogreenstreets.org](mailto:info@gogreenstreets.org). We’re always growing the network.",
    "faq.badges-streaks-tiers.title": "Badges, Streaks & Tiers",
    "faq.badges-streaks-tiers.1.q": "What are the tier levels?",
    "faq.badges-streaks-tiers.1.a": "Shift has five tiers: Starter, Mover, Shifter, Pacesetter, and Trailblazer. You move up by taking active trips and keeping a strong 60-day Shift Rate. Each step up earns more XP per trip, and every partner offer opens at Mover.",
    "faq.badges-streaks-tiers.2.q": "What is Shift Rate?",
    "faq.badges-streaks-tiers.2.a": "Shift Rate is the share of your trips that weren’t made by driving: walking, biking, scooting, transit or carpooling. Home shows your 60-day Shift Rate, the same one that sets your tier, so a single off-week doesn’t bump you down.",
    "faq.badges-streaks-tiers.3.q": "How do achievement badges work?",
    "faq.badges-streaks-tiers.3.a": "Achievement badges are earned by reaching specific milestones — trying new modes, building streaks, hitting cumulative distance goals, completing Roams, and more. The Progress tab shows which badges you’ve unlocked and what’s next. Most badges award bonus XP when earned.",
    "faq.badges-streaks-tiers.4.q": "What is a Featured Goal?",
    "faq.badges-streaks-tiers.4.a": "A Featured Goal is a 14-day sprint highlighting the next badge you’re closest to earning. If you complete the goal within the 14-day window, you get a 50% XP bonus on top of the badge’s normal XP.",
    "faq.badges-streaks-tiers.5.q": "How do streaks work?",
    "faq.badges-streaks-tiers.5.a": "A streak counts the days when you take at least one active trip (walking, biking, transit, or e-scooter). You get a 2-day grace window — miss up to two days in a row and the streak stays alive. Three days in a row without an active trip resets it. New to Shift? Home counts weeks in a row with an active trip until your daily streak reaches 3 days. We also protect your streak during significant MBTA service disruptions, and if you’re going away, turn on Vacation mode in Profile > Settings and your streak waits for you.",
    "faq.badges-streaks-tiers.6.q": "What happens if I break a streak?",
    "faq.badges-streaks-tiers.6.a": "Your current streak resets to 1, but your longest streak is saved on your profile. Streaks are meant to be motivating, not punishing — start a new one whenever you’re ready.",
    "faq.roams.title": "Roams",
    "faq.roams.1.q": "What is a Roam?",
    "faq.roams.1.a": "A Roam is a curated outing — a set of checkpoints along a walking, biking, transit, or multi-modal route that you visit in any order. Think of it as a self-guided tour that rewards you for exploring your city by active transportation. Roams range from quick neighborhood loops to longer cross-city adventures.",
    "faq.roams.2.q": "How do I start a Roam?",
    "faq.roams.2.a": "Open the Community tab and look for available Roams. Tap one to see its checkpoints on a map, the estimated distance, and which modes are recommended (walk, bike, transit, or any combination). When you’re ready, tap Start this Roam. The app will track your progress as you visit each checkpoint.",
    "faq.roams.3.q": "How does checkpoint detection work?",
    "faq.roams.3.a": "As you move near a checkpoint, the app detects your arrival automatically using your phone’s location. If auto-detection doesn’t trigger (GPS can be imprecise in dense areas), you can tap the checkpoint on the map and use the manual check-in button when you’re nearby. Either way counts the same.",
    "faq.roams.4.q": "Do I need to visit every checkpoint?",
    "faq.roams.4.a": "Most Roams require visiting all checkpoints to complete. Some trail Roams need only some of their stops, and bonus stops are always optional. The Roam detail screen shows how many checkpoints you need.",
    "faq.roams.5.q": "Do I need to follow a specific route between checkpoints?",
    "faq.roams.5.a": "No. You choose your own path between checkpoints. The map shows checkpoint locations, but how you get between them is up to you. Walk, bike, or take transit — whatever the Roam’s recommended modes include.",
    "faq.roams.6.q": "What do I earn for completing a Roam?",
    "faq.roams.6.a": "Completing a Roam earns you a badge and XP. Some Roams are part of collections — finish all Roams in a collection for a bonus badge.",
    "faq.roams.7.q": "Any safety tips for Roams?",
    "faq.roams.7.a": "Always follow traffic laws and use sidewalks, bike lanes, and crosswalks. Stay aware of your surroundings — don’t stare at your phone while moving. Plan your route before you start, especially for longer Roams. Bring water, wear weather-appropriate gear, and let someone know your plans for longer outings. The app is a guide, not a GPS navigator — use your own judgment about safe routes.",
    "faq.competitions.title": "Drawings & Challenges",
    "faq.competitions.1.q": "What is Walk/Ride Day?",
    "faq.competitions.1.a": "One day a month, every walking, biking or transit trip you record in Shift enters you in a prize drawing. Entry is automatic, with nothing to sign up for. It’s open to Massachusetts residents 18 and older, and no purchase is necessary. The [Walk/Ride Day page](/programs/walk-ride-days) has the dates and prizes, and the [official rules](/events/walk-ride-day/rules) have the details.",
    "faq.competitions.2.q": "Are there other challenges?",
    "faq.competitions.2.a": "Workplaces and groups that use Shift run their own challenges, and you’ll see them in the app if you belong to one. Shift also gives gift cards for trying something new, like making a regular trip by bike or transit.",
    "faq.competitions.3.q": "How are winners chosen, and what happens if I win?",
    "faq.competitions.3.a": "Winners are drawn at random from all eligible entries after the drawing closes. Trips Shift tracked, or that you fixed or confirmed, earn entries; trips added with Log past trip don’t. If you win, we’ll email you and send a notice in the app. Claim your prize in the Rewards tab within the time shown.",
    "faq.competitions.4.q": "What happened to Shift Your Summer?",
    "faq.competitions.4.a": "Shift Your Summer ran from June to August 2026 and has ended. Its [official rules](/events/shift-your-summer/rules) are still online.",
    "faq.for-rewards-partners.title": "For Rewards Partners",
    "faq.for-rewards-partners.1.q": "How do I become a Shift Rewards Partner?",
    "faq.for-rewards-partners.1.a": "We’d love to have you. Visit [gogreenstreets.org/shift/rewards-partners](/shift/rewards-partners) or email [info@gogreenstreets.org](mailto:info@gogreenstreets.org). We’ll walk you through the setup — it’s simple and free to participate.",
    "faq.for-rewards-partners.2.q": "How do I verify a Shift redemption?",
    "faq.for-rewards-partners.2.a": "When a customer wants to use a Shift offer, they’ll show you their tier badge on the app screen. That’s your green light to apply the offer — no need to log into a dashboard at the time. When you join, we’ll provide a [1-page printed guide](/cashier-guide.html) you can keep at the register.",
    "faq.for-rewards-partners.3.q": "How do I access my business dashboard?",
    "faq.for-rewards-partners.3.a": "Go to [gogreenstreets.org/shift/rewards-partners](/shift/rewards-partners) and enter your email under Partner login. We’ll send you a sign-in link. Your dashboard shows your offer, redemptions and locations.",
    "faq.for-rewards-partners.4.q": "What does it cost to be a Rewards Partner?",
    "faq.for-rewards-partners.4.a": "Nothing. There are no fees to join the Shift Rewards Partner network. You set the reward you’re comfortable offering, and you benefit from exposure to an engaged community of sustainability-minded local customers.",
    "faq.for-rewards-partners.5.q": "Can I change or pause my reward offer?",
    "faq.for-rewards-partners.5.a": "Yes. From your dashboard you can edit your offer, turn locations on or off, and pause your listing. While it’s paused, your offer and locations are hidden in the app until you reactivate. To change who qualifies, email us at info@gogreenstreets.org.",
    "faq.for-schools.title": "For Schools",
    "faq.for-schools.1.q": "How does the Shift for Schools program work?",
    "faq.for-schools.1.a": "Shift for Schools is a classroom-based active transportation challenge. Each day, teachers take a quick tally using a simple show of hands to see how students got to school. Classrooms earn recognition for walking, biking, and taking transit — and can compete within and across schools. The program is designed to be fun, easy to run, and fully COPPA-compliant. No student accounts or personal data are collected.",
    "faq.for-schools.2.q": "How do classroom codes work?",
    "faq.for-schools.2.a": "Each participating classroom receives a unique 6-character code. The teacher uses this code to submit the classroom’s daily tally through the [Shift for Schools portal](/shift/schools). Codes are assigned during program setup and stay the same for the duration of the challenge.",
    "faq.for-schools.3.q": "I’m a School Coordinator — where do I start?",
    "faq.for-schools.3.a": "Welcome! As School Coordinator, you’re the main point of contact between your school and Green Streets Initiative. Start by reviewing the program overview and School Coordinator Quick-Start Card we’ll share during onboarding. Your first steps are confirming participating classrooms, distributing classroom codes to teachers, and sharing the parent information sheet. Reach out to [info@gogreenstreets.org](mailto:info@gogreenstreets.org) any time.",
    "faq.for-schools.4.q": "I’m a parent — how can I help?",
    "faq.for-schools.4.a": "Parents play a key role as Parent Volunteers and Walk & Bike Bus Leaders. A Walk & Bike Bus is a group of families who walk or bike a set route to school together. If you’re interested in starting or joining one, talk to your School Coordinator or email [info@gogreenstreets.org](mailto:info@gogreenstreets.org).",
    "faq.for-schools.5.q": "Is student data private?",
    "faq.for-schools.5.a": "Yes. Shift for Schools is designed with student privacy at its core. No individual student accounts are created. Data is collected at the classroom level only (e.g., \"12 students walked today\") — no names, locations, or personal information are ever involved. The program is fully COPPA-compliant.",
    "faq.for-schools.6.q": "Can students use the Shift app?",
    "faq.for-schools.6.a": "The Shift app is for people 13 and older, and some features are for adults 18 and older. The Shift for Schools classroom challenge is a separate, app-free experience — students participate through their teacher’s daily show-of-hands tally without needing any device or account.",
    "faq.privacy-data.title": "Privacy & Data",
    "faq.privacy-data.1.q": "What data does Shift collect?",
    "faq.privacy-data.1.a": "Your email, your name, the places you save, and your trips (where they start and end, distance, time and mode). Also anything you choose to add: a school or work email, workouts imported from Apple Health or Health Connect, and your birth date if you enter a prize drawing. If you use the AI assistant, your conversations go to Anthropic’s Claude to answer you, and we keep them for 12 months. We never sell your personal data. For full details, see our [Privacy Policy](/privacy).",
    "faq.privacy-data.2.q": "How is my location data used?",
    "faq.privacy-data.2.a": "Location data is used to detect and record your trips: to calculate distances, identify how you traveled, and count your trips toward your town’s and groups’ leaderboards. We do not share raw location data with third parties.",
    "faq.privacy-data.3.q": "Who can see my profile?",
    "faq.privacy-data.3.a": "Profiles are public by default, so others in Shift can see your name, photo and badges, and you appear on leaderboards. To hide them, turn off Public profile in Profile > Settings > Privacy. Your trips still count for your groups either way.",
    "faq.privacy-data.4.q": "How do I delete my account and data?",
    "faq.privacy-data.4.a": "Go to Profile > Settings > Account > Delete account. This permanently removes your profile and trip history. If you have any trouble, email [info@gogreenstreets.org](mailto:info@gogreenstreets.org) and we’ll take care of it.",
    "faq.account-settings.title": "Account & Settings",
    "faq.account-settings.1.q": "How do I sign in? Is there a password?",
    "faq.account-settings.1.a": "Shift doesn’t use passwords. Enter your email on the sign-in screen and we’ll send you a sign-in link; open it on the same phone. You can also continue with Google, or with Apple on an iPhone. If a link doesn’t work, send yourself a new one, and check your spam folder.",
    "faq.account-settings.2.q": "How do I change my name or neighborhood?",
    "faq.account-settings.2.a": "Profile > Edit profile changes your name and photo. Your neighborhood follows your Home place, which you can change in Profile > Your places.",
    "faq.account-settings.3.q": "Can I use Shift in another language?",
    "faq.account-settings.3.a": "Yes. Shift is available in English, Spanish, Portuguese and Chinese. Choose yours in Profile > Settings > Language.",
    "faq.account-settings.4.q": "How do I update Shift or see my version?",
    "faq.account-settings.4.a": "Most updates install on their own the next time you open Shift. Profile > Help shows your version and when it last updated. For bigger updates, the App Store or Google Play will offer the new version.",
    "faq.account-settings.5.q": "How do I get help or send feedback from inside the app?",
    "faq.account-settings.5.a": "Open Profile > Help. Tap **Help & FAQ** to come right back to this page, or **Send feedback** to email us with your phone and app details filled in. You can also email [info@gogreenstreets.org](mailto:info@gogreenstreets.org) directly.",
    "faq.account-settings.6.q": "I’m having a technical issue not listed here.",
    "faq.account-settings.6.a": "Use **Send feedback** in Profile > Help. It fills in your phone model, OS and app version, and a short tracking summary (no locations), which helps us find the problem quickly. Or email [info@gogreenstreets.org](mailto:info@gogreenstreets.org) with a description and a screenshot if you have one. We’ll get back to you as quickly as we can.",
  },
  {
    "es": {
      "help.meta_title": "Ayuda — Green Streets Initiative",
      "help.meta_description": "Todo lo que necesitas saber para usar Shift, desbloquear recompensas, organizar un desafío escolar o sumarte como socio.",
      "help.title": "¿Cómo podemos ayudarte?",
      "help.intro": "Todo lo que necesitas saber para usar Shift, desbloquear recompensas, organizar un desafío escolar o sumarte como socio.",
      "help.card_app_users": "Usuarios de la app",
      "help.card_partners": "Socios de recompensas",
      "help.card_schools": "Escuelas",
      "help.still_title": "¿Todavía necesitas ayuda?",
      "help.still_body": "Somos un equipo pequeño y leemos cada mensaje. Escríbenos y te responderemos lo antes posible.",
      "help.general_support": "Soporte general",
      "faq.getting-started.title": "Primeros pasos",
      "faq.getting-started.1.q": "¿Qué es Shift?",
      "faq.getting-started.1.a": "Shift es una app gratuita de Green Streets Initiative que registra sola tus viajes a pie, en bici, en scooter y en transporte público, y te premia por ellos. Ganas XP, insignias y niveles, desbloqueas ofertas en negocios locales, recibes tarjetas de regalo por probar nuevas formas de moverte y participas en sorteos mensuales de premios como el Walk/Ride Day. También te muestra los próximos autobuses y trenes cerca de ti y planea rutas.",
      "faq.getting-started.2.q": "¿Cómo descargo la app Shift?",
      "faq.getting-started.2.a": "Shift está disponible en el App Store (iPhone) y en Google Play (Android). Busca “Shift by Green Streets Initiative” o usa los enlaces de descarga de nuestra [página principal](/).",
      "faq.getting-started.3.q": "¿Cómo creo una cuenta?",
      "faq.getting-started.3.a": "Abre la app e ingresa tu correo, y te enviaremos un enlace para iniciar sesión. También puedes continuar con Google, o con Apple en un iPhone. Luego agrega tu nombre. Para aparecer en la clasificación de tu ciudad, agrega tu Casa en Perfil > Tus lugares.",
      "faq.getting-started.4.q": "¿Shift es realmente gratis?",
      "faq.getting-started.4.a": "Sí. Shift es totalmente gratis para descargar y usar. No hay planes premium, compras dentro de la app ni cargos ocultos.",
      "faq.getting-started.5.q": "¿Qué recibo por invitar a mis amigos?",
      "faq.getting-started.5.a": "Tu código de invitación está en Perfil > Invitar amigos. Cuando un amigo se une con tu código y hace 5 viajes, recibes $10 para gastar en un negocio local.",
      "faq.trip-tracking.title": "Seguimiento de tus viajes",
      "faq.trip-tracking.1.q": "¿Cómo funciona el seguimiento de viajes?",
      "faq.trip-tracking.1.a": "Shift usa la ubicación de tu teléfono en segundo plano para notar cuándo caminas, vas en bici, en scooter o en transporte público. Cada viaje se guarda con su distancia, duración y modo, y aparece en tu historial de viajes. Cuando Shift no está seguro de cómo viajaste, te pregunta.",
      "faq.trip-tracking.2.q": "¿Qué formas de moverse cuentan?",
      "faq.trip-tracking.2.a": "Los viajes a pie, en bici, en autobús, en metro, en tren de cercanías, en ferry, en scooter eléctrico y en auto compartido ganan XP. Los viajes en auto compartido no cuentan para tu nivel. Manejar no gana nada.",
      "faq.trip-tracking.3.q": "Shift dejó de registrar mis viajes. ¿Cómo lo arreglo?",
      "faq.trip-tracking.3.a": "Tres pasos resuelven la mayoría de los casos. En los Ajustes de tu teléfono, abre Shift y pon Ubicación en Siempre (Permitir todo el tiempo en Android). Activa Movimiento y forma física en un iPhone, o Actividad física en Android. Luego abre Shift, que vuelve a registrar. Perfil > Configuración > Seguimiento de viajes muestra cualquier otra cosa desactivada, como Ubicación exacta o Actualización en segundo plano, con un botón para arreglarla, y una tarjeta arriba en Inicio también te guía. Los viajes de menos de 0.1 milla o 2 minutos no se guardan, y los túneles o las estaciones subterráneas a veces pueden hacer que se pierda un viaje.",
      "faq.trip-tracking.4.q": "Se cerró mi sesión. ¿Perdí mis viajes?",
      "faq.trip-tracking.4.a": "No. Mientras tu sesión está cerrada, Shift guarda los viajes que registra hasta por 30 días y los envía cuando vuelves a iniciar sesión.",
      "faq.trip-tracking.5.q": "¿Puedo agregar un viaje que Shift no registró?",
      "faq.trip-tracking.5.a": "Sí. Toca Registrar viaje pasado en la tarjeta de seguimiento de Inicio y elige cómo viajaste, la distancia y el día, hasta una semana atrás. Los viajes agregados así ganan XP y cuentan para tu nivel, pero no ganan participaciones en sorteos ni tarjetas de regalo. Para que un viaje cuente para eso, toca Iniciar viaje al salir. También puedes importar caminatas y recorridos en bici desde Apple Health o Health Connect en Perfil > Configuración > Seguimiento de viajes.",
      "faq.trip-tracking.6.q": "¿Cómo corrijo un modo de viaje equivocado?",
      "faq.trip-tracking.6.a": "Abre el viaje y elige el modo correcto. Un viaje que corriges o confirmas cuenta completo: XP, participaciones en sorteos y recompensas.",
      "faq.trip-tracking.7.q": "¿Cuentan los viajes fuera de Massachusetts?",
      "faq.trip-tracking.7.a": "Shift los guarda, pero cuando un viaje empieza y termina fuera de Massachusetts, solo las caminatas ganan XP y participaciones en sorteos. Si vas a estar fuera un tiempo, puedes activar el Modo vacaciones en Perfil > Configuración.",
      "faq.trip-tracking.8.q": "¿Qué tan preciso es el seguimiento en segundo plano?",
      "faq.trip-tracking.8.a": "El seguimiento en segundo plano suele ser preciso dentro de un margen razonable. La precisión del GPS varía según el entorno: las zonas urbanas densas con edificios altos y el transporte subterráneo pueden reducirla. La app usa filtros inteligentes para distinguir los modos, pero a veces puede clasificar mal un viaje.",
      "faq.trip-tracking.9.q": "¿El seguimiento gasta mi batería?",
      "faq.trip-tracking.9.a": "Shift usa servicios de ubicación en segundo plano eficientes, diseñados para gastar poca batería. La mayoría de las personas casi no nota diferencia. Si notas un problema, asegúrate de tener al día el sistema de tu teléfono y la app Shift.",
      "faq.getting-around.title": "Cómo moverte",
      "faq.getting-around.1.q": "¿Cómo veo las salidas cerca de mí o planeo un viaje?",
      "faq.getting-around.1.a": "Cerca de ti, en la pantalla de Inicio, muestra los próximos autobuses y trenes cerca de ti y las bicis cercanas. Toca Planear una ruta para obtener indicaciones a cualquier lugar. Puedes guardar un viaje que haces seguido, y aparece en Inicio y en Perfil > Tus viajes.",
      "faq.getting-around.2.q": "Sé andar en bici, pero el tráfico me pone nervioso. ¿Puedo tomar una clase?",
      "faq.getting-around.2.a": "Sí. Si vives cerca de Somerville, Green Streets cubre el costo de una clase individual gratis en la calle con la Bicycle Riding School: 90 minutos en calles reales, a tu ritmo, una por persona mientras haya clases. Pídela en nuestra [página de clases de bici](/bike-lessons#street-lesson) (no necesitas la app) o en la app, y un instructor te escribe para elegir un horario. ¿Vives más lejos o prefieres esperar a la primavera? La misma página muestra clases e instructores en todo Massachusetts y puede avisarte por correo cuando vuelvan las clases.",
      "faq.getting-around.3.q": "¿Cómo funciona Shift Together?",
      "faq.getting-around.3.a": "Presentamos a quienes quieren empezar a ir en bici o a tomar el T a alguien cerca que ya lo hace, y van juntos la primera vez. Regístrate con dónde vives, adónde quieres ir y si prefieres ir en bici o en el T. Shift te sugiere a alguien que vive a un par de millas de ti. Cada uno ve solo el nombre de pila, nunca una dirección. Si los dos dicen que sí, cada uno ve el correo del otro para planear el primer viaje, y Shift sugiere un lugar público para encontrarse. Puedes terminar una pareja cuando quieras con \"¿Algo salió mal?\". [Regístrate](/together)",
      "faq.points-rewards.title": "XP y recompensas",
      "faq.points-rewards.1.q": "¿Cómo funcionan las recompensas?",
      "faq.points-rewards.1.a": "Hay dos tipos. Las ofertas en negocios locales (descuentos, regalos y beneficios para miembros) se abren cuando llegas a Mover, el segundo nivel. No gastas XP en ellas; tu nivel es tu llave. Las tarjetas de regalo llegan por ganar un sorteo, completar un desafío, probar una nueva forma de hacer un viaje habitual o invitar a un amigo.",
      "faq.points-rewards.2.q": "¿Cómo gano XP?",
      "faq.points-rewards.2.a": "Ganas XP cada vez que haces un viaje activo (a pie, en bici, en transporte público, en auto compartido o en scooter eléctrico). La cantidad por viaje depende de tu nivel: Starter gana 1 XP por viaje, Mover 2, Shifter 3, Pacesetter 4 y Trailblazer 5. Puedes ganar hasta 15 XP al día por viajes. Además, ganas XP extra al alcanzar hitos de insignias (rachas, distancias, variedad de modos) y al subir de nivel. Durante una Meta Destacada, completar la meta a tiempo te da un 50% más de XP en la insignia. Los viajes agregados con Registrar viaje pasado también ganan XP, pero no participaciones en sorteos ni tarjetas de regalo.",
      "faq.points-rewards.3.q": "¿El XP es una moneda que puedo gastar?",
      "faq.points-rewards.3.a": "No. El XP es un registro de tu progreso, no una billetera. Te hace subir de nivel y muestra cuánto has avanzado, pero nunca lo gastas para canjear una oferta. Las ofertas de los Socios de recompensas se desbloquean con tu nivel.",
      "faq.points-rewards.4.q": "Recibí una tarjeta de regalo. ¿Cómo la uso?",
      "faq.points-rewards.4.a": "Abre la pestaña Recompensas, toca Tus recompensas y elige dónde gastarla antes de la fecha límite. Las tarjetas de regalo de marca llegan al instante; las de tiendas locales tardan un par de días hábiles.",
      "faq.points-rewards.5.q": "¿Cómo encuentro y uso una oferta de un Socio de recompensas?",
      "faq.points-rewards.5.a": "La pestaña Recompensas muestra cada oferta de los socios con su ubicación y detalles. Todas se abren en Mover. Para usar una en una tienda, muestra al cajero tu insignia de nivel en la pantalla de la oferta. Para ofertas en línea, usa el código o el enlace que aparece en la app.",
      "faq.points-rewards.6.q": "¿Dónde veo mi XP y mi nivel?",
      "faq.points-rewards.6.a": "Tu nivel está arriba en Inicio; tócalo para ver los detalles. Tu total de XP y tu historial están en la pestaña Progreso.",
      "faq.points-rewards.7.q": "¿El XP vence?",
      "faq.points-rewards.7.a": "El XP mide tu progreso, así que no hay nada que \"venza\": tu XP de siempre y tu historial de niveles siempre forman parte de tu perfil. Si dejas de usar la app por mucho tiempo, podríamos archivar las cuentas inactivas, pero mientras uses Shift tu progreso está a salvo.",
      "faq.points-rewards.8.q": "Un Socio de recompensas no respetó una oferta a la que debería tener derecho. ¿Qué hago?",
      "faq.points-rewards.8.a": "Escríbenos a [info@gogreenstreets.org](mailto:info@gogreenstreets.org) con el nombre del socio, la fecha y lo que pasó. Lo resolveremos directamente con el socio para que recibas la oferta.",
      "faq.points-rewards.9.q": "¿Puedo sugerir un negocio como Socio de recompensas?",
      "faq.points-rewards.9.a": "¡Claro! Si hay un negocio local que te encantaría ver en la red de Shift, avísanos en [info@gogreenstreets.org](mailto:info@gogreenstreets.org). Siempre estamos haciendo crecer la red.",
      "faq.badges-streaks-tiers.title": "Insignias, rachas y niveles",
      "faq.badges-streaks-tiers.1.q": "¿Cuáles son los niveles?",
      "faq.badges-streaks-tiers.1.a": "Shift tiene cinco niveles: Starter, Mover, Shifter, Pacesetter y Trailblazer. Subes haciendo viajes activos y manteniendo un buen Shift Rate de 60 días. Cada nivel gana más XP por viaje, y todas las ofertas de los socios se abren en Mover.",
      "faq.badges-streaks-tiers.2.q": "¿Qué es el Shift Rate?",
      "faq.badges-streaks-tiers.2.a": "El Shift Rate es la parte de tus viajes que no hiciste manejando: a pie, en bici, en scooter, en transporte público o en auto compartido. Inicio muestra tu Shift Rate de 60 días, el mismo que define tu nivel, así que una sola semana floja no te baja de nivel.",
      "faq.badges-streaks-tiers.3.q": "¿Cómo funcionan las insignias de logros?",
      "faq.badges-streaks-tiers.3.a": "Las insignias de logros se ganan al alcanzar hitos concretos: probar nuevos modos, mantener rachas, llegar a metas de distancia acumulada, completar Roams y más. La pestaña Progreso muestra qué insignias desbloqueaste y cuál sigue. La mayoría de las insignias dan XP extra al ganarlas.",
      "faq.badges-streaks-tiers.4.q": "¿Qué es una Meta Destacada?",
      "faq.badges-streaks-tiers.4.a": "Una Meta Destacada es un reto de 14 días centrado en la insignia que tienes más cerca de ganar. Si completas la meta dentro de esos 14 días, recibes un 50% más de XP además del XP normal de la insignia.",
      "faq.badges-streaks-tiers.5.q": "¿Cómo funcionan las rachas?",
      "faq.badges-streaks-tiers.5.a": "Una racha cuenta los días en que haces al menos un viaje activo (a pie, en bici, en transporte público o en scooter eléctrico). Tienes 2 días de margen: si faltas hasta dos días seguidos, la racha sigue viva. Tres días seguidos sin un viaje activo la reinician. ¿Eres nuevo en Shift? Inicio cuenta las semanas seguidas con un viaje activo hasta que tu racha diaria llega a 3 días. También protegemos tu racha durante interrupciones importantes del servicio de la MBTA, y si vas de viaje, activa el Modo vacaciones en Perfil > Configuración y tu racha te espera.",
      "faq.badges-streaks-tiers.6.q": "¿Qué pasa si rompo una racha?",
      "faq.badges-streaks-tiers.6.a": "Tu racha actual vuelve a 1, pero tu racha más larga queda guardada en tu perfil. Las rachas son para motivarte, no para castigarte: empieza una nueva cuando quieras.",
      "faq.roams.title": "Roams",
      "faq.roams.1.q": "¿Qué es un Roam?",
      "faq.roams.1.a": "Un Roam es una salida preparada: un conjunto de puntos de control a lo largo de una ruta a pie, en bici, en transporte público o combinada, que visitas en el orden que quieras. Piensa en un recorrido autoguiado que te premia por explorar tu ciudad con transporte activo. Hay Roams desde vueltas cortas por el barrio hasta aventuras más largas por la ciudad.",
      "faq.roams.2.q": "¿Cómo empiezo un Roam?",
      "faq.roams.2.a": "Abre la pestaña Comunidad y busca los Roams disponibles. Toca uno para ver sus puntos de control en un mapa, la distancia estimada y los modos recomendados (a pie, en bici, en transporte público o una combinación). Cuando estés listo, toca Iniciar este Roam. La app registra tu progreso a medida que visitas cada punto de control.",
      "faq.roams.3.q": "¿Cómo se detectan los puntos de control?",
      "faq.roams.3.a": "Cuando te acercas a un punto de control, la app detecta tu llegada automáticamente con la ubicación de tu teléfono. Si la detección automática no se activa (el GPS puede fallar en zonas densas), puedes tocar el punto de control en el mapa y usar el botón para registrarte a mano cuando estés cerca. Las dos formas cuentan igual.",
      "faq.roams.4.q": "¿Tengo que visitar todos los puntos de control?",
      "faq.roams.4.a": "La mayoría de los Roams requieren visitar todos los puntos de control para completarlos. Algunos Roams de senderos solo piden algunas de sus paradas, y las paradas extra siempre son opcionales. La pantalla de detalles del Roam muestra cuántos puntos de control necesitas.",
      "faq.roams.5.q": "¿Tengo que seguir una ruta específica entre los puntos de control?",
      "faq.roams.5.a": "No. Tú eliges tu camino entre los puntos de control. El mapa muestra dónde están, pero cómo llegas de uno a otro depende de ti. Camina, ve en bici o toma el transporte público, según los modos recomendados del Roam.",
      "faq.roams.6.q": "¿Qué gano por completar un Roam?",
      "faq.roams.6.a": "Completar un Roam te da una insignia y XP. Algunos Roams forman parte de colecciones: termina todos los Roams de una colección para ganar una insignia extra.",
      "faq.roams.7.q": "¿Algún consejo de seguridad para los Roams?",
      "faq.roams.7.a": "Respeta siempre las normas de tránsito y usa las aceras, las ciclovías y los cruces peatonales. Presta atención a tu alrededor: no mires el teléfono mientras te mueves. Planea tu ruta antes de salir, sobre todo en los Roams más largos. Lleva agua, vístete según el clima y avisa a alguien de tus planes en las salidas largas. La app es una guía, no un navegador GPS: usa tu propio criterio para elegir rutas seguras.",
      "faq.competitions.title": "Sorteos y desafíos",
      "faq.competitions.1.q": "¿Qué es el Walk/Ride Day?",
      "faq.competitions.1.a": "Un día al mes, cada viaje a pie, en bici o en transporte público que registras en Shift te hace participar en un sorteo de premios. La participación es automática, sin nada que llenar. Está abierto a residentes de Massachusetts de 18 años o más, y no hace falta comprar nada. La [página del Walk/Ride Day](/programs/walk-ride-days) tiene las fechas y los premios, y las [reglas oficiales](/events/walk-ride-day/rules) tienen los detalles.",
      "faq.competitions.2.q": "¿Hay otros desafíos?",
      "faq.competitions.2.a": "Los lugares de trabajo y los grupos que usan Shift organizan sus propios desafíos, y los verás en la app si perteneces a uno. Shift también da tarjetas de regalo por probar algo nuevo, como hacer un viaje habitual en bici o en transporte público.",
      "faq.competitions.3.q": "¿Cómo se eligen los ganadores y qué pasa si gano?",
      "faq.competitions.3.a": "Los ganadores se sortean al azar entre todas las participaciones válidas cuando cierra el sorteo. Los viajes que Shift registró, o que corregiste o confirmaste, ganan participaciones; los agregados con Registrar viaje pasado no. Si ganas, te escribiremos por correo y te avisaremos en la app. Reclama tu premio en la pestaña Recompensas dentro del plazo indicado.",
      "faq.competitions.4.q": "¿Qué pasó con Shift Your Summer?",
      "faq.competitions.4.a": "Shift Your Summer se realizó de junio a agosto de 2026 y ya terminó. Sus [reglas oficiales](/events/shift-your-summer/rules) siguen en línea.",
      "faq.for-rewards-partners.title": "Para Socios de recompensas",
      "faq.for-rewards-partners.1.q": "¿Cómo me convierto en Socio de recompensas de Shift?",
      "faq.for-rewards-partners.1.a": "Nos encantaría tenerte. Visita [gogreenstreets.org/shift/rewards-partners](/shift/rewards-partners) o escribe a [info@gogreenstreets.org](mailto:info@gogreenstreets.org). Te guiaremos en la configuración: es sencillo y participar es gratis.",
      "faq.for-rewards-partners.2.q": "¿Cómo verifico un canje de Shift?",
      "faq.for-rewards-partners.2.a": "Cuando un cliente quiera usar una oferta de Shift, te mostrará su insignia de nivel en la pantalla de la app. Esa es tu luz verde para aplicar la oferta; no necesitas entrar a un panel en ese momento. Cuando te unas, te daremos una [guía impresa de 1 página](/cashier-guide.html) para tener en la caja.",
      "faq.for-rewards-partners.3.q": "¿Cómo entro al panel de mi negocio?",
      "faq.for-rewards-partners.3.a": "Ve a [gogreenstreets.org/shift/rewards-partners](/shift/rewards-partners) e ingresa tu correo en Partner login. Te enviaremos un enlace para iniciar sesión. Tu panel muestra tu oferta, los canjes y tus ubicaciones.",
      "faq.for-rewards-partners.4.q": "¿Cuánto cuesta ser Socio de recompensas?",
      "faq.for-rewards-partners.4.a": "Nada. No hay cargos por unirte a la red de Socios de recompensas de Shift. Tú decides la recompensa que te conviene ofrecer, y te das a conocer ante una comunidad activa de clientes locales que se preocupan por la sostenibilidad.",
      "faq.for-rewards-partners.5.q": "¿Puedo cambiar o pausar mi oferta?",
      "faq.for-rewards-partners.5.a": "Sí. Desde tu panel puedes editar tu oferta, activar o desactivar ubicaciones y pausar tu publicación. Mientras está pausada, tu oferta y tus ubicaciones no aparecen en la app hasta que la reactives. Para cambiar quién califica, escríbenos a info@gogreenstreets.org.",
      "faq.for-schools.title": "Para escuelas",
      "faq.for-schools.1.q": "¿Cómo funciona el programa Shift for Schools?",
      "faq.for-schools.1.a": "Shift for Schools es un desafío de transporte activo que se hace en el salón de clases. Cada día, los maestros hacen un conteo rápido a mano alzada para ver cómo llegaron los estudiantes a la escuela. Los salones ganan reconocimiento por caminar, ir en bici y usar el transporte público, y pueden competir dentro de su escuela y con otras. El programa está pensado para ser divertido, fácil de organizar y cumplir por completo con COPPA. No se crean cuentas de estudiantes ni se recogen datos personales.",
      "faq.for-schools.2.q": "¿Cómo funcionan los códigos de salón?",
      "faq.for-schools.2.a": "Cada salón participante recibe un código único de 6 caracteres. El maestro usa ese código para enviar el conteo diario del salón en el [portal de Shift for Schools](/shift/schools). Los códigos se asignan al configurar el programa y no cambian durante todo el desafío.",
      "faq.for-schools.3.q": "Soy coordinador escolar. ¿Por dónde empiezo?",
      "faq.for-schools.3.a": "¡Bienvenido! Como coordinador escolar, eres el principal contacto entre tu escuela y Green Streets Initiative. Empieza por revisar el resumen del programa y la tarjeta de inicio rápido para coordinadores que compartiremos al comenzar. Tus primeros pasos son confirmar los salones participantes, repartir los códigos de salón a los maestros y compartir la hoja informativa para las familias. Escríbenos a [info@gogreenstreets.org](mailto:info@gogreenstreets.org) cuando quieras.",
      "faq.for-schools.4.q": "Soy madre o padre. ¿Cómo puedo ayudar?",
      "faq.for-schools.4.a": "Las familias tienen un papel clave como voluntarias y como líderes de Walk & Bike Bus. Un Walk & Bike Bus es un grupo de familias que van juntas a la escuela a pie o en bici por una ruta fija. Si te interesa empezar uno o unirte, habla con el coordinador de tu escuela o escribe a [info@gogreenstreets.org](mailto:info@gogreenstreets.org).",
      "faq.for-schools.5.q": "¿Los datos de los estudiantes son privados?",
      "faq.for-schools.5.a": "Sí. Shift for Schools está diseñado con la privacidad de los estudiantes como base. No se crean cuentas individuales de estudiantes. Los datos se recogen solo a nivel de salón (por ejemplo, \"12 estudiantes caminaron hoy\"): nunca se usan nombres, ubicaciones ni información personal. El programa cumple por completo con COPPA.",
      "faq.for-schools.6.q": "¿Los estudiantes pueden usar la app Shift?",
      "faq.for-schools.6.a": "La app Shift es para personas de 13 años o más, y algunas funciones son para adultos de 18 o más. El desafío de salón de Shift for Schools es una experiencia aparte, sin app: los estudiantes participan con el conteo diario a mano alzada de su maestro, sin necesitar ningún dispositivo ni cuenta.",
      "faq.privacy-data.title": "Privacidad y datos",
      "faq.privacy-data.1.q": "¿Qué datos recoge Shift?",
      "faq.privacy-data.1.a": "Tu correo, tu nombre, los lugares que guardas y tus viajes (dónde empiezan y terminan, distancia, duración y modo). También lo que decidas agregar: un correo de la escuela o del trabajo, entrenamientos importados de Apple Health o Health Connect, y tu fecha de nacimiento si participas en un sorteo de premios. Si usas el asistente de IA, tus conversaciones van a Claude de Anthropic para responderte, y las guardamos por 12 meses. Nunca vendemos tus datos personales. Para todos los detalles, consulta nuestra [Política de privacidad](/privacy).",
      "faq.privacy-data.2.q": "¿Cómo se usan mis datos de ubicación?",
      "faq.privacy-data.2.a": "Los datos de ubicación se usan para detectar y registrar tus viajes: calcular distancias, identificar cómo viajaste y sumar tus viajes a las clasificaciones de tu ciudad y tus grupos. No compartimos datos de ubicación sin procesar con terceros.",
      "faq.privacy-data.3.q": "¿Quién puede ver mi perfil?",
      "faq.privacy-data.3.a": "Los perfiles son públicos por defecto, así que otras personas en Shift pueden ver tu nombre, tu foto y tus insignias, y apareces en las clasificaciones. Para ocultarlos, desactiva Perfil público en Perfil > Configuración > Privacidad. Tus viajes siguen contando para tus grupos de todas formas.",
      "faq.privacy-data.4.q": "¿Cómo elimino mi cuenta y mis datos?",
      "faq.privacy-data.4.a": "Ve a Perfil > Configuración > Cuenta > Eliminar cuenta. Esto borra para siempre tu perfil y tu historial de viajes. Si tienes algún problema, escribe a [info@gogreenstreets.org](mailto:info@gogreenstreets.org) y nos encargamos.",
      "faq.account-settings.title": "Cuenta y configuración",
      "faq.account-settings.1.q": "¿Cómo inicio sesión? ¿Hay contraseña?",
      "faq.account-settings.1.a": "Shift no usa contraseñas. Ingresa tu correo en la pantalla de inicio de sesión y te enviaremos un enlace; ábrelo en el mismo teléfono. También puedes continuar con Google, o con Apple en un iPhone. Si un enlace no funciona, pide uno nuevo y revisa tu carpeta de spam.",
      "faq.account-settings.2.q": "¿Cómo cambio mi nombre o mi barrio?",
      "faq.account-settings.2.a": "Perfil > Editar perfil cambia tu nombre y tu foto. Tu barrio sigue a tu lugar Casa, que puedes cambiar en Perfil > Tus lugares.",
      "faq.account-settings.3.q": "¿Puedo usar Shift en otro idioma?",
      "faq.account-settings.3.a": "Sí. Shift está disponible en inglés, español, portugués y chino. Elige el tuyo en Perfil > Configuración > Idioma.",
      "faq.account-settings.4.q": "¿Cómo actualizo Shift o veo mi versión?",
      "faq.account-settings.4.a": "La mayoría de las actualizaciones se instalan solas la próxima vez que abres Shift. Perfil > Ayuda muestra tu versión y cuándo se actualizó por última vez. Para actualizaciones más grandes, el App Store o Google Play te ofrecerán la nueva versión.",
      "faq.account-settings.5.q": "¿Cómo pido ayuda o envío comentarios desde la app?",
      "faq.account-settings.5.a": "Abre Perfil > Ayuda. Toca **Ayuda y preguntas frecuentes** para volver a esta página, o **Enviar comentarios** para escribirnos con los datos de tu teléfono y de la app ya incluidos. También puedes escribir directamente a [info@gogreenstreets.org](mailto:info@gogreenstreets.org).",
      "faq.account-settings.6.q": "Tengo un problema técnico que no aparece aquí.",
      "faq.account-settings.6.a": "Usa **Enviar comentarios** en Perfil > Ayuda. Incluye el modelo de tu teléfono, la versión del sistema y de la app, y un breve resumen del seguimiento (sin ubicaciones), lo que nos ayuda a encontrar el problema rápido. O escribe a [info@gogreenstreets.org](mailto:info@gogreenstreets.org) con una descripción y una captura de pantalla si tienes una. Te responderemos lo antes posible.",
    },
    "pt-BR": {
      "help.meta_title": "Ajuda — Green Streets Initiative",
      "help.meta_description": "Tudo o que você precisa saber para usar o Shift, liberar recompensas, organizar um desafio na escola ou entrar como parceiro.",
      "help.title": "Como podemos ajudar?",
      "help.intro": "Tudo o que você precisa saber para usar o Shift, liberar recompensas, organizar um desafio na escola ou entrar como parceiro.",
      "help.card_app_users": "Quem usa o app",
      "help.card_partners": "Parceiros de recompensas",
      "help.card_schools": "Escolas",
      "help.still_title": "Ainda precisa de ajuda?",
      "help.still_body": "Somos uma equipe pequena e lemos todas as mensagens. Fale com a gente e responderemos o mais rápido possível.",
      "help.general_support": "Suporte geral",
      "faq.getting-started.title": "Primeiros passos",
      "faq.getting-started.1.q": "O que é o Shift?",
      "faq.getting-started.1.a": "O Shift é um app gratuito da Green Streets Initiative que registra sozinho suas viagens a pé, de bike, de patinete e de transporte público, e recompensa você por elas. Você ganha XP, badges e níveis, libera ofertas em negócios locais, ganha cartões-presente por experimentar novas formas de se locomover e participa de sorteios mensais de prêmios, como o Walk/Ride Day. Ele também mostra os próximos ônibus e trens perto de você e planeja rotas.",
      "faq.getting-started.2.q": "Como baixo o app Shift?",
      "faq.getting-started.2.a": "O Shift está disponível na App Store (iPhone) e no Google Play (Android). Procure “Shift by Green Streets Initiative” ou use os links de download na nossa [página inicial](/).",
      "faq.getting-started.3.q": "Como crio uma conta?",
      "faq.getting-started.3.a": "Abra o app e digite seu e-mail: enviaremos um link de login. Você também pode continuar com Google, ou com Apple no iPhone. Depois, adicione seu nome. Para aparecer na classificação da sua cidade, adicione sua Casa em Perfil > Seus lugares.",
      "faq.getting-started.4.q": "O Shift é mesmo gratuito?",
      "faq.getting-started.4.a": "Sim. O Shift é totalmente gratuito para baixar e usar. Não há planos premium, compras no app nem taxas escondidas.",
      "faq.getting-started.5.q": "O que ganho por convidar amigos?",
      "faq.getting-started.5.a": "Seu código de convite fica em Perfil > Convidar amigos. Quando um amigo entra com seu código e faz 5 viagens, você ganha US$ 10 para gastar num negócio local.",
      "faq.trip-tracking.title": "Registro das suas viagens",
      "faq.trip-tracking.1.q": "Como funciona o registro de viagens?",
      "faq.trip-tracking.1.a": "O Shift usa a localização do seu celular em segundo plano para perceber quando você anda, pedala, usa patinete ou pega transporte público. Cada viagem é salva com distância, horário e modo, e aparece no seu histórico. Quando o Shift não tem certeza de como você foi, ele pergunta.",
      "faq.trip-tracking.2.q": "Quais formas de se locomover contam?",
      "faq.trip-tracking.2.a": "Viagens a pé, de bike, de ônibus, de metrô, de trem, de barca, de patinete elétrico e de carona dão XP. Caronas não contam para o seu nível. Dirigir não dá nada.",
      "faq.trip-tracking.3.q": "O Shift parou de registrar minhas viagens. Como resolvo?",
      "faq.trip-tracking.3.a": "Três passos resolvem a maioria dos casos. Nos Ajustes do celular, abra o Shift e coloque Localização em Sempre (Permitir o tempo todo no Android). Ative Movimento e Preparo Físico no iPhone, ou Atividade física no Android. Depois abra o Shift, que volta a registrar. Perfil > Configurações > Rastreamento de viagens mostra o que mais estiver desligado, como Localização Precisa ou Atualização em segundo plano, com um botão para corrigir, e um cartão no topo do Início também guia você. Viagens com menos de 0,1 milha ou 2 minutos não são salvas, e túneis ou estações subterrâneas às vezes fazem uma viagem não ser registrada.",
      "faq.trip-tracking.4.q": "Fui desconectado. Perdi minhas viagens?",
      "faq.trip-tracking.4.a": "Não. Enquanto você está desconectado, o Shift guarda as viagens que registra por até 30 dias e as envia quando você entra de novo.",
      "faq.trip-tracking.5.q": "Posso adicionar uma viagem que o Shift não registrou?",
      "faq.trip-tracking.5.a": "Sim. Toque em Registrar viagem passada no cartão de registro do Início e escolha como você foi, a distância e o dia, até uma semana atrás. Viagens adicionadas assim dão XP e contam para o seu nível, mas não dão participações em sorteios nem recompensas em cartão-presente. Para uma viagem valer para isso, toque em Iniciar Viagem quando sair. Você também pode importar caminhadas e pedaladas do Apple Health ou do Health Connect em Perfil > Configurações > Rastreamento de viagens.",
      "faq.trip-tracking.6.q": "Como corrijo um modo de viagem errado?",
      "faq.trip-tracking.6.a": "Abra a viagem e escolha o modo certo. Uma viagem que você corrige ou confirma conta por inteiro: XP, participações em sorteios e recompensas.",
      "faq.trip-tracking.7.q": "Viagens fora de Massachusetts contam?",
      "faq.trip-tracking.7.a": "O Shift as salva, mas quando uma viagem começa e termina fora de Massachusetts, só caminhadas dão XP e participações em sorteios. Se você vai ficar fora por um tempo, pode ativar o Modo férias em Perfil > Configurações.",
      "faq.trip-tracking.8.q": "Quão preciso é o registro em segundo plano?",
      "faq.trip-tracking.8.a": "O registro em segundo plano costuma ser preciso, dentro de uma margem razoável. A precisão do GPS varia conforme o ambiente: áreas urbanas densas, com prédios altos e transporte subterrâneo, podem reduzi-la. O app usa filtros inteligentes para distinguir os modos, mas às vezes pode errar a classificação.",
      "faq.trip-tracking.9.q": "O registro gasta muita bateria?",
      "faq.trip-tracking.9.a": "O Shift usa serviços de localização em segundo plano eficientes, feitos para gastar pouca bateria. A maioria das pessoas nota um consumo extra mínimo. Se notar algum problema, confira se o sistema do celular e o app Shift estão atualizados.",
      "faq.getting-around.title": "Como se locomover",
      "faq.getting-around.1.q": "Como vejo as partidas perto de mim ou planejo uma viagem?",
      "faq.getting-around.1.a": "Perto de você, na tela Início, mostra os próximos ônibus e trens perto de você e as bikes próximas. Toque em Planejar uma rota para ver como chegar a qualquer lugar. Você pode salvar uma viagem que faz sempre, e ela aparece no Início e em Perfil > Suas viagens.",
      "faq.getting-around.2.q": "Sei pedalar, mas o trânsito me deixa nervoso. Posso ter uma aula?",
      "faq.getting-around.2.a": "Sim. Se você mora perto de Somerville, a Green Streets paga uma aula individual gratuita na rua com a Bicycle Riding School: 90 minutos em ruas de verdade, no seu ritmo, uma por pessoa enquanto houver vagas. Peça a sua na nossa [página de aulas de bike](/bike-lessons#street-lesson) (sem precisar do app) ou no app, e um instrutor manda um e-mail para marcar o horário. Mora mais longe ou prefere esperar a primavera? A mesma página lista aulas e instrutores em todo Massachusetts e pode avisar você por e-mail quando as aulas voltarem.",
      "faq.getting-around.3.q": "Como funciona o Shift Together?",
      "faq.getting-around.3.a": "Apresentamos quem quer começar a pedalar ou a pegar o T a alguém perto que já faz isso, e vocês vão juntos na primeira vez. Cadastre-se com onde você mora, aonde quer ir e se prefere ir de bike ou de T. O Shift sugere alguém que mora a umas duas milhas de você. Cada um vê só o primeiro nome, nunca um endereço. Se os dois disserem sim, cada um vê o e-mail do outro para planejar a primeira viagem, e o Shift sugere um lugar público para se encontrarem. Você pode encerrar a dupla quando quiser em \"Algo deu errado?\". [Cadastre-se](/together)",
      "faq.points-rewards.title": "XP e recompensas",
      "faq.points-rewards.1.q": "Como funcionam as recompensas?",
      "faq.points-rewards.1.a": "Há dois tipos. As ofertas em negócios locais (descontos, brindes e vantagens para membros) liberam quando você chega a Mover, o segundo nível. Você não gasta XP com elas; seu nível é a sua chave. Os cartões-presente vêm de ganhar um sorteio, completar um desafio, experimentar um novo jeito de fazer uma viagem de sempre ou convidar um amigo.",
      "faq.points-rewards.2.q": "Como ganho XP?",
      "faq.points-rewards.2.a": "Você ganha XP toda vez que faz uma viagem ativa (a pé, de bike, de transporte público, de carona ou de patinete elétrico). A quantidade por viagem depende do seu nível: Starter ganha 1 XP por viagem, Mover 2, Shifter 3, Pacesetter 4 e Trailblazer 5. Você pode ganhar até 15 XP por dia com viagens. Além disso, ganha XP de bônus ao atingir marcos de badges (sequências, distâncias, variedade de modos) e ao subir de nível. Durante uma Meta em Destaque, completar a meta a tempo dá 50% de XP de bônus no badge. Viagens adicionadas com Registrar viagem passada também dão XP, mas não participações em sorteios nem recompensas em cartão-presente.",
      "faq.points-rewards.3.q": "XP é uma moeda que posso gastar?",
      "faq.points-rewards.3.a": "Não. XP é um registro do seu progresso, não uma carteira. Ele faz você subir de nível e mostra quanto você já avançou, mas você nunca o gasta para resgatar uma oferta. As ofertas dos Parceiros de recompensas são liberadas pelo seu nível.",
      "faq.points-rewards.4.q": "Ganhei um cartão-presente. Como uso?",
      "faq.points-rewards.4.a": "Abra a aba Recompensas, toque em Suas recompensas e escolha onde gastar antes da data limite. Cartões de marcas chegam na hora; cartões de lojas locais levam alguns dias úteis.",
      "faq.points-rewards.5.q": "Como encontro e uso uma oferta de um Parceiro de recompensas?",
      "faq.points-rewards.5.a": "A aba Recompensas lista todas as ofertas dos parceiros com local e detalhes. Todas liberam a partir de Mover. Para usar uma na loja, mostre ao caixa o selo do seu nível na tela da oferta. Para ofertas online, use o código ou o link que aparece no app.",
      "faq.points-rewards.6.q": "Onde vejo meu XP e meu nível?",
      "faq.points-rewards.6.a": "Seu nível fica no topo do Início; toque nele para ver detalhes. Seu total de XP e o histórico ficam na aba Progresso.",
      "faq.points-rewards.7.q": "O XP expira?",
      "faq.points-rewards.7.a": "XP é uma medida de progresso, então não há nada para \"expirar\": seu XP total e seu histórico de níveis fazem sempre parte do seu perfil. Se você ficar muito tempo sem usar o app, podemos arquivar contas inativas, mas enquanto você usar o Shift, seu progresso está seguro.",
      "faq.points-rewards.8.q": "Um Parceiro de recompensas não aceitou uma oferta a que eu tinha direito. O que faço?",
      "faq.points-rewards.8.a": "Mande um e-mail para [info@gogreenstreets.org](mailto:info@gogreenstreets.org) com o nome do parceiro, a data e o que aconteceu. Resolveremos direto com o parceiro para você receber a oferta.",
      "faq.points-rewards.9.q": "Posso sugerir um negócio como Parceiro de recompensas?",
      "faq.points-rewards.9.a": "Claro. Se há um negócio local que você adoraria ver na rede do Shift, conte para a gente em [info@gogreenstreets.org](mailto:info@gogreenstreets.org). A rede está sempre crescendo.",
      "faq.badges-streaks-tiers.title": "Badges, sequências e níveis",
      "faq.badges-streaks-tiers.1.q": "Quais são os níveis?",
      "faq.badges-streaks-tiers.1.a": "O Shift tem cinco níveis: Starter, Mover, Shifter, Pacesetter e Trailblazer. Você sobe fazendo viagens ativas e mantendo uma boa Taxa Shift de 60 dias. Cada nível acima dá mais XP por viagem, e todas as ofertas dos parceiros liberam a partir de Mover.",
      "faq.badges-streaks-tiers.2.q": "O que é a Taxa Shift?",
      "faq.badges-streaks-tiers.2.a": "A Taxa Shift é a parte das suas viagens que não foram de carro: a pé, de bike, de patinete, de transporte público ou de carona. O Início mostra sua Taxa Shift de 60 dias, a mesma que define seu nível, então uma semana fraca não faz você cair.",
      "faq.badges-streaks-tiers.3.q": "Como funcionam os badges de conquista?",
      "faq.badges-streaks-tiers.3.a": "Os badges de conquista são ganhos ao atingir marcos específicos: experimentar novos modos, manter sequências, alcançar metas de distância acumulada, completar Roams e mais. A aba Progresso mostra quais badges você já liberou e qual é o próximo. A maioria dos badges dá XP de bônus quando conquistada.",
      "faq.badges-streaks-tiers.4.q": "O que é uma Meta em Destaque?",
      "faq.badges-streaks-tiers.4.a": "Uma Meta em Destaque é um desafio de 14 dias com o próximo badge que você está mais perto de ganhar. Se você completar a meta dentro dos 14 dias, ganha 50% de XP de bônus além do XP normal do badge.",
      "faq.badges-streaks-tiers.5.q": "Como funcionam as sequências?",
      "faq.badges-streaks-tiers.5.a": "Uma sequência conta os dias em que você faz pelo menos uma viagem ativa (a pé, de bike, de transporte público ou de patinete elétrico). Você tem 2 dias de tolerância: pode ficar até dois dias seguidos sem viagem e a sequência continua. Três dias seguidos sem viagem ativa a zeram. Novo no Shift? O Início conta semanas seguidas com uma viagem ativa até sua sequência diária chegar a 3 dias. Também protegemos sua sequência durante interrupções importantes do serviço da MBTA, e se você for viajar, ative o Modo férias em Perfil > Configurações e sua sequência espera por você.",
      "faq.badges-streaks-tiers.6.q": "O que acontece se eu quebrar uma sequência?",
      "faq.badges-streaks-tiers.6.a": "Sua sequência atual volta para 1, mas a mais longa fica salva no seu perfil. As sequências servem para motivar, não para punir: comece uma nova quando quiser.",
      "faq.roams.title": "Roams",
      "faq.roams.1.q": "O que é um Roam?",
      "faq.roams.1.a": "Um Roam é um passeio selecionado: um conjunto de pontos de parada ao longo de uma rota a pé, de bike, de transporte público ou combinando modos, que você visita em qualquer ordem. Pense nele como um passeio autoguiado que recompensa você por explorar sua cidade de forma ativa. Há Roams desde voltas rápidas pelo bairro até aventuras mais longas pela cidade.",
      "faq.roams.2.q": "Como começo um Roam?",
      "faq.roams.2.a": "Abra a aba Comunidade e procure os Roams disponíveis. Toque em um para ver os pontos de parada no mapa, a distância estimada e os modos recomendados (a pé, de bike, de transporte público ou qualquer combinação). Quando estiver pronto, toque em Começar este Roam. O app acompanha seu progresso a cada ponto que você visita.",
      "faq.roams.3.q": "Como funciona a detecção dos pontos de parada?",
      "faq.roams.3.a": "Quando você chega perto de um ponto de parada, o app detecta sua chegada automaticamente pela localização do celular. Se a detecção automática não funcionar (o GPS pode ser impreciso em áreas densas), você pode tocar no ponto no mapa e usar o botão de check-in manual quando estiver perto. As duas formas contam igual.",
      "faq.roams.4.q": "Preciso visitar todos os pontos de parada?",
      "faq.roams.4.a": "A maioria dos Roams exige visitar todos os pontos para completar. Alguns Roams de trilha pedem só parte das paradas, e as paradas bônus são sempre opcionais. A tela de detalhes do Roam mostra quantos pontos você precisa.",
      "faq.roams.5.q": "Preciso seguir uma rota específica entre os pontos de parada?",
      "faq.roams.5.a": "Não. Você escolhe seu caminho entre os pontos. O mapa mostra onde ficam, mas como ir de um a outro é com você. A pé, de bike ou de transporte público, conforme os modos recomendados do Roam.",
      "faq.roams.6.q": "O que ganho ao completar um Roam?",
      "faq.roams.6.a": "Completar um Roam dá um badge e XP. Alguns Roams fazem parte de coleções: complete todos os Roams de uma coleção e ganhe um badge bônus.",
      "faq.roams.7.q": "Alguma dica de segurança para os Roams?",
      "faq.roams.7.a": "Respeite sempre as leis de trânsito e use calçadas, ciclovias e faixas de pedestres. Fique atento ao redor: não fique olhando o celular enquanto se move. Planeje sua rota antes de começar, principalmente nos Roams mais longos. Leve água, use roupas adequadas ao clima e avise alguém dos seus planos em passeios longos. O app é um guia, não um navegador GPS: use seu próprio julgamento sobre rotas seguras.",
      "faq.competitions.title": "Sorteios e desafios",
      "faq.competitions.1.q": "O que é o Walk/Ride Day?",
      "faq.competitions.1.a": "Um dia por mês, cada viagem a pé, de bike ou de transporte público que você registra no Shift coloca você num sorteio de prêmios. A participação é automática, sem inscrição. É aberto a residentes de Massachusetts com 18 anos ou mais, e não é preciso comprar nada. A [página do Walk/Ride Day](/programs/walk-ride-days) tem as datas e os prêmios, e o [regulamento oficial](/events/walk-ride-day/rules) tem os detalhes.",
      "faq.competitions.2.q": "Há outros desafios?",
      "faq.competitions.2.a": "Empresas e grupos que usam o Shift fazem seus próprios desafios, e você os vê no app se fizer parte de um deles. O Shift também dá cartões-presente por experimentar algo novo, como fazer uma viagem de sempre de bike ou de transporte público.",
      "faq.competitions.3.q": "Como os ganhadores são escolhidos e o que acontece se eu ganhar?",
      "faq.competitions.3.a": "Os ganhadores são sorteados entre todas as participações válidas depois que o sorteio termina. Viagens que o Shift registrou, ou que você corrigiu ou confirmou, dão participações; viagens adicionadas com Registrar viagem passada, não. Se você ganhar, mandaremos um e-mail e um aviso no app. Resgate seu prêmio na aba Recompensas dentro do prazo indicado.",
      "faq.competitions.4.q": "O que aconteceu com o Shift Your Summer?",
      "faq.competitions.4.a": "O Shift Your Summer foi de junho a agosto de 2026 e já terminou. O [regulamento oficial](/events/shift-your-summer/rules) continua online.",
      "faq.for-rewards-partners.title": "Para Parceiros de recompensas",
      "faq.for-rewards-partners.1.q": "Como me torno um Parceiro de recompensas do Shift?",
      "faq.for-rewards-partners.1.a": "Vamos adorar ter você. Visite [gogreenstreets.org/shift/rewards-partners](/shift/rewards-partners) ou mande um e-mail para [info@gogreenstreets.org](mailto:info@gogreenstreets.org). Vamos guiar você na configuração: é simples e gratuito participar.",
      "faq.for-rewards-partners.2.q": "Como confirmo um resgate do Shift?",
      "faq.for-rewards-partners.2.a": "Quando um cliente quiser usar uma oferta do Shift, ele mostra o selo do seu nível na tela do app. É o sinal verde para aplicar a oferta, sem precisar entrar num painel na hora. Quando você entrar, enviaremos um [guia impresso de 1 página](/cashier-guide.html) para deixar no caixa.",
      "faq.for-rewards-partners.3.q": "Como acesso o painel do meu negócio?",
      "faq.for-rewards-partners.3.a": "Acesse [gogreenstreets.org/shift/rewards-partners](/shift/rewards-partners) e digite seu e-mail em Partner login. Enviaremos um link de login. Seu painel mostra sua oferta, os resgates e os locais.",
      "faq.for-rewards-partners.4.q": "Quanto custa ser um Parceiro de recompensas?",
      "faq.for-rewards-partners.4.a": "Nada. Não há taxas para entrar na rede de Parceiros de recompensas do Shift. Você define a recompensa que se sente à vontade para oferecer e ganha visibilidade com uma comunidade engajada de clientes locais que se importam com a sustentabilidade.",
      "faq.for-rewards-partners.5.q": "Posso mudar ou pausar minha oferta?",
      "faq.for-rewards-partners.5.a": "Sim. No seu painel você pode editar a oferta, ligar ou desligar locais e pausar seu anúncio. Enquanto estiver pausado, sua oferta e seus locais ficam ocultos no app até você reativar. Para mudar quem tem direito, mande um e-mail para info@gogreenstreets.org.",
      "faq.for-schools.title": "Para escolas",
      "faq.for-schools.1.q": "Como funciona o programa Shift for Schools?",
      "faq.for-schools.1.a": "O Shift for Schools é um desafio de mobilidade ativa feito em sala de aula. Todo dia, os professores fazem uma contagem rápida, com os alunos levantando a mão, para ver como eles chegaram à escola. As turmas ganham reconhecimento por ir a pé, de bike e de transporte público, e podem competir dentro da escola e entre escolas. O programa foi feito para ser divertido, fácil de organizar e totalmente de acordo com a COPPA. Não há contas de alunos nem coleta de dados pessoais.",
      "faq.for-schools.2.q": "Como funcionam os códigos das turmas?",
      "faq.for-schools.2.a": "Cada turma participante recebe um código único de 6 caracteres. O professor usa esse código para enviar a contagem diária da turma pelo [portal do Shift for Schools](/shift/schools). Os códigos são definidos na configuração do programa e não mudam durante o desafio.",
      "faq.for-schools.3.q": "Sou coordenador escolar. Por onde começo?",
      "faq.for-schools.3.a": "Boas-vindas! Como coordenador escolar, você é o principal contato entre sua escola e a Green Streets Initiative. Comece revisando a visão geral do programa e o Guia Rápido do Coordenador Escolar que enviaremos na integração. Seus primeiros passos são confirmar as turmas participantes, distribuir os códigos das turmas aos professores e compartilhar a folha de informações para as famílias. Fale com [info@gogreenstreets.org](mailto:info@gogreenstreets.org) quando quiser.",
      "faq.for-schools.4.q": "Sou pai ou mãe. Como posso ajudar?",
      "faq.for-schools.4.a": "Pais e mães têm um papel importante como voluntários e líderes de Walk & Bike Bus. Um Walk & Bike Bus é um grupo de famílias que vai a pé ou de bike até a escola juntas por uma rota fixa. Se você quer começar ou entrar em um, fale com o coordenador escolar ou mande um e-mail para [info@gogreenstreets.org](mailto:info@gogreenstreets.org).",
      "faq.for-schools.5.q": "Os dados dos alunos são privados?",
      "faq.for-schools.5.a": "Sim. O Shift for Schools foi feito com a privacidade dos alunos como base. Nenhuma conta individual de aluno é criada. Os dados são coletados só por turma (por exemplo, \"12 alunos vieram a pé hoje\"), sem nomes, locais ou informações pessoais. O programa está totalmente de acordo com a COPPA.",
      "faq.for-schools.6.q": "Os alunos podem usar o app Shift?",
      "faq.for-schools.6.a": "O app Shift é para pessoas a partir de 13 anos, e alguns recursos são para adultos a partir de 18. O desafio em sala de aula do Shift for Schools é uma experiência separada e sem app: os alunos participam pela contagem diária do professor, com as mãos levantadas, sem precisar de aparelho ou conta.",
      "faq.privacy-data.title": "Privacidade e dados",
      "faq.privacy-data.1.q": "Quais dados o Shift coleta?",
      "faq.privacy-data.1.a": "Seu e-mail, seu nome, os lugares que você salva e suas viagens (onde começam e terminam, distância, horário e modo). Também o que você escolher adicionar: um e-mail da escola ou do trabalho, treinos importados do Apple Health ou do Health Connect e sua data de nascimento, se participar de um sorteio de prêmios. Se você usar o assistente de IA, suas conversas vão para o Claude, da Anthropic, para responder você, e as guardamos por 12 meses. Nunca vendemos seus dados pessoais. Para todos os detalhes, veja nossa [Política de Privacidade](/privacy).",
      "faq.privacy-data.2.q": "Como meus dados de localização são usados?",
      "faq.privacy-data.2.a": "Os dados de localização servem para detectar e registrar suas viagens: calcular distâncias, identificar como você foi e contar suas viagens nas classificações da sua cidade e dos seus grupos. Não compartilhamos dados brutos de localização com terceiros.",
      "faq.privacy-data.3.q": "Quem pode ver meu perfil?",
      "faq.privacy-data.3.a": "Os perfis são públicos por padrão, então outras pessoas no Shift podem ver seu nome, foto e badges, e você aparece nas classificações. Para ocultar, desligue Perfil público em Perfil > Configurações > Privacidade. Suas viagens continuam contando para seus grupos de qualquer jeito.",
      "faq.privacy-data.4.q": "Como excluo minha conta e meus dados?",
      "faq.privacy-data.4.a": "Vá em Perfil > Configurações > Conta > Excluir conta. Isso remove para sempre seu perfil e seu histórico de viagens. Se tiver algum problema, mande um e-mail para [info@gogreenstreets.org](mailto:info@gogreenstreets.org) e resolvemos para você.",
      "faq.account-settings.title": "Conta e configurações",
      "faq.account-settings.1.q": "Como entro? Tem senha?",
      "faq.account-settings.1.a": "O Shift não usa senhas. Digite seu e-mail na tela de login e enviaremos um link de login; abra-o no mesmo celular. Você também pode continuar com Google, ou com Apple no iPhone. Se um link não funcionar, peça um novo e olhe a pasta de spam.",
      "faq.account-settings.2.q": "Como mudo meu nome ou meu bairro?",
      "faq.account-settings.2.a": "Em Perfil > Editar perfil você muda seu nome e sua foto. Seu bairro segue o lugar Casa, que você pode mudar em Perfil > Seus lugares.",
      "faq.account-settings.3.q": "Posso usar o Shift em outro idioma?",
      "faq.account-settings.3.a": "Sim. O Shift está disponível em inglês, espanhol, português e chinês. Escolha o seu em Perfil > Configurações > Idioma.",
      "faq.account-settings.4.q": "Como atualizo o Shift ou vejo minha versão?",
      "faq.account-settings.4.a": "A maioria das atualizações é instalada sozinha na próxima vez que você abre o Shift. Perfil > Ajuda mostra sua versão e quando foi a última atualização. Para atualizações maiores, a App Store ou o Google Play vão oferecer a nova versão.",
      "faq.account-settings.5.q": "Como peço ajuda ou envio feedback de dentro do app?",
      "faq.account-settings.5.a": "Abra Perfil > Ajuda. Toque em **Ajuda e perguntas frequentes** para voltar a esta página, ou em **Enviar feedback** para mandar um e-mail com os dados do seu celular e do app já preenchidos. Você também pode escrever direto para [info@gogreenstreets.org](mailto:info@gogreenstreets.org).",
      "faq.account-settings.6.q": "Tenho um problema técnico que não está aqui.",
      "faq.account-settings.6.a": "Use **Enviar feedback** em Perfil > Ajuda. Ele preenche o modelo do celular, o sistema, a versão do app e um breve resumo do registro (sem locais), o que nos ajuda a achar o problema rápido. Ou mande um e-mail para [info@gogreenstreets.org](mailto:info@gogreenstreets.org) com uma descrição e uma captura de tela, se tiver. Responderemos o mais rápido possível.",
    },
    "zh-Hans": {
      "help.meta_title": "帮助 — Green Streets Initiative",
      "help.meta_description": "关于使用 Shift、解锁奖励、开展学校挑战或成为合作伙伴，你需要知道的一切。",
      "help.title": "需要什么帮助？",
      "help.intro": "关于使用 Shift、解锁奖励、开展学校挑战或成为合作伙伴，你需要知道的一切。",
      "help.card_app_users": "应用用户",
      "help.card_partners": "奖励合作伙伴",
      "help.card_schools": "学校",
      "help.still_title": "还需要帮助？",
      "help.still_body": "我们是一个小团队，每条消息都会认真阅读。联系我们，我们会尽快回复你。",
      "help.general_support": "一般支持",
      "faq.getting-started.title": "入门",
      "faq.getting-started.1.q": "Shift 是什么？",
      "faq.getting-started.1.a": "Shift 是 Green Streets Initiative 推出的免费应用，会自动记录你的步行、骑行、滑板车和公共交通出行，并为此奖励你。你可以获得 XP、徽章和等级，解锁本地商家的优惠，尝试新的出行方式还能获得礼品卡，并自动参加 Walk/Ride Day 等每月抽奖。它还会显示你附近即将到站的公交和列车，并帮你规划路线。",
      "faq.getting-started.2.q": "如何下载 Shift 应用？",
      "faq.getting-started.2.a": "Shift 可在 App Store（iPhone）和 Google Play（Android）下载。搜索“Shift by Green Streets Initiative”，或使用我们[首页](/)上的下载链接。",
      "faq.getting-started.3.q": "如何创建账户？",
      "faq.getting-started.3.a": "打开应用并输入你的电子邮箱，我们会给你发送登录链接。你也可以用 Google 继续，或在 iPhone 上用 Apple 继续。然后填写你的名字。想出现在你所在城镇的排行榜上，请在 个人资料 > 你的地点 中添加你的“家”。",
      "faq.getting-started.4.q": "Shift 真的免费吗？",
      "faq.getting-started.4.a": "是的。Shift 下载和使用完全免费，没有高级版、应用内购买或隐藏费用。",
      "faq.getting-started.5.q": "邀请好友能得到什么？",
      "faq.getting-started.5.a": "你的邀请码在 个人资料 > 邀请好友 中。好友用你的邀请码加入并完成 5 次出行后，你会获得 10 美元，可在本地商家消费。",
      "faq.trip-tracking.title": "记录你的出行",
      "faq.trip-tracking.1.q": "出行记录是怎么运作的？",
      "faq.trip-tracking.1.a": "Shift 会在后台使用手机定位，识别你何时在步行、骑行、骑滑板车或乘坐公共交通。每次出行都会保存距离、时间和出行方式，并显示在你的出行记录中。Shift 不确定你是怎么出行的时候，会询问你。",
      "faq.trip-tracking.2.q": "哪些出行方式算数？",
      "faq.trip-tracking.2.a": "步行、骑行、公交、地铁、通勤铁路、渡轮、电动滑板车和拼车出行都能获得 XP。拼车不计入你的等级。开车不会获得任何奖励。",
      "faq.trip-tracking.3.q": "Shift 不再记录我的出行了，怎么解决？",
      "faq.trip-tracking.3.a": "三个步骤能解决大多数情况。在手机的“设置”中打开 Shift，把位置权限设为“始终”（Android 上为“一直允许”）。在 iPhone 上打开“运动与健身”，在 Android 上打开“身体活动”。然后打开 Shift，它会重新开始记录。个人资料 > 设置 > 行程追踪 会显示其他未开启的项目，比如精确位置或后台 App 刷新，并附有修复按钮；主页顶部的卡片也会一步步引导你。不到 0.1 英里或 2 分钟的出行不会保存，隧道或地下车站偶尔也可能导致漏记。",
      "faq.trip-tracking.4.q": "我被退出登录了，我的出行记录丢了吗？",
      "faq.trip-tracking.4.a": "没有。退出登录期间，Shift 会保留它记录的出行最多 30 天，等你重新登录后再上传。",
      "faq.trip-tracking.5.q": "Shift 漏记的出行可以手动添加吗？",
      "faq.trip-tracking.5.a": "可以。在主页的追踪卡片上点击“记录过往出行”，然后选择出行方式、距离和日期，最多可追溯一周。这样添加的出行能获得 XP 并计入你的等级，但不会获得抽奖机会或礼品卡奖励。想让出行计入这些，请在出发时点击“开始出行”。你也可以在 个人资料 > 设置 > 行程追踪 中导入 Apple Health 或 Health Connect 里的步行和骑行记录。",
      "faq.trip-tracking.6.q": "出行方式记错了怎么改？",
      "faq.trip-tracking.6.a": "打开这次出行，选择正确的出行方式。你修正或确认过的出行会完整计算：XP、抽奖机会和奖励都有。",
      "faq.trip-tracking.7.q": "马萨诸塞州以外的出行算数吗？",
      "faq.trip-tracking.7.a": "Shift 会保存这些出行，但如果出行的起点和终点都在马萨诸塞州以外，只有步行能获得 XP 和抽奖机会。如果你要离开一段时间，可以在 个人资料 > 设置 中开启度假模式。",
      "faq.trip-tracking.8.q": "后台记录准确吗？",
      "faq.trip-tracking.8.a": "后台记录总体上准确，误差在合理范围内。GPS 精度会因环境而异：高楼密集的市区和地下交通可能降低准确度。应用会用智能筛选来区分出行方式，但偶尔也可能识别错误。",
      "faq.trip-tracking.9.q": "记录出行会很耗电吗？",
      "faq.trip-tracking.9.a": "Shift 使用高效的后台定位服务，尽量减少耗电。大多数用户几乎感觉不到额外耗电。如果你发现问题，请确认手机系统和 Shift 应用都已更新到最新版本。",
      "faq.getting-around.title": "出行",
      "faq.getting-around.1.q": "怎么查看附近的班次或规划行程？",
      "faq.getting-around.1.a": "主页上的“您的周边”会显示你附近即将到站的公交和列车，以及附近可用的自行车。点击“规划路线”可获取去任何地方的路线。你可以保存常走的行程，它会显示在主页和 个人资料 > 我的行程 中。",
      "faq.getting-around.2.q": "我会骑车，但车流让我紧张。可以上一节课吗？",
      "faq.getting-around.2.a": "可以。如果你住在 Somerville 附近，Green Streets 会为你支付与 Bicycle Riding School 的一节免费一对一道路课程：在真实街道上骑 90 分钟，按你的节奏来，每人一节，名额有限。可以在我们的[自行车课程页面](/bike-lessons#street-lesson)申请（无需应用），也可以在应用中申请，教练会发邮件和你约时间。住得更远，或想等到春天？同一页面列出了马萨诸塞州各地的课程和教练，课程重新开始时还可以发邮件通知你。",
      "faq.getting-around.3.q": "Shift Together 是怎么运作的？",
      "faq.getting-around.3.a": "我们为想开始骑车或坐地铁（T）的人介绍一位住在附近、已经这样出行的人，第一次你们一起去。注册时填写你住在哪里、想去哪里，以及想骑车还是坐地铁。Shift 会推荐一位住在你几英里范围内的人。你们只能看到对方的名字，绝不会看到地址。如果双方都同意，你们会看到对方的电子邮箱来计划第一次出行，Shift 还会推荐一个公共场所见面。你可以随时通过“遇到问题？”结束配对。[立即注册](/together)",
      "faq.points-rewards.title": "XP 和奖励",
      "faq.points-rewards.1.q": "奖励是怎么运作的？",
      "faq.points-rewards.1.a": "奖励有两种。本地商家的优惠（折扣、免费赠品和会员优惠）在你达到第二个等级 Mover 后解锁。这些优惠不用花 XP，你的等级就是钥匙。礼品卡来自抽奖中奖、完成挑战、用新方式完成一段常走的行程，或邀请好友。",
      "faq.points-rewards.2.q": "怎么获得 XP？",
      "faq.points-rewards.2.a": "每次绿色出行（步行、骑行、公共交通、拼车或电动滑板车）都能获得 XP。每次出行获得多少取决于你的等级：Starter 每次 1 XP，Mover 2 XP，Shifter 3 XP，Pacesetter 4 XP，Trailblazer 5 XP。每天通过出行最多可获得 15 XP。此外，达成徽章里程碑（连续天数、距离、多种出行方式）和等级晋升时还能获得额外 XP。在精选目标冲刺期间，按时完成目标可在该徽章上额外获得 50% 的 XP。通过“记录过往出行”添加的出行也能获得 XP，但不会获得抽奖机会或礼品卡奖励。",
      "faq.points-rewards.3.q": "XP 是可以花的货币吗？",
      "faq.points-rewards.3.a": "不是。XP 是你进步的记录，不是钱包。它推动你的等级提升，也显示你走了多远，但兑换优惠时从不需要花 XP。奖励合作伙伴的优惠由你的等级解锁。",
      "faq.points-rewards.4.q": "我获得了一张礼品卡，怎么使用？",
      "faq.points-rewards.4.a": "打开“奖励”标签，点击“你的奖励”，在选择截止日期前选好在哪里使用。品牌礼品卡会立即到账；本地商店的礼品卡需要几个工作日。",
      "faq.points-rewards.5.q": "怎么找到并使用奖励合作伙伴的优惠？",
      "faq.points-rewards.5.a": "“奖励”标签列出了每个合作伙伴的优惠，包括地点和详情。所有优惠都在 Mover 等级解锁。在店内使用时，向收银员出示优惠页面上的等级徽章。线上优惠请使用应用中显示的优惠码或链接。",
      "faq.points-rewards.6.q": "在哪里查看我的 XP 和等级？",
      "faq.points-rewards.6.a": "你的等级在主页顶部，点击可查看详情。你的 XP 总数和记录在“进度”标签中。",
      "faq.points-rewards.7.q": "XP 会过期吗？",
      "faq.points-rewards.7.a": "XP 是衡量进步的指标，所以不存在“过期”：你累计的 XP 和等级记录会一直保留在你的个人资料中。如果你很长时间不用应用，我们可能会归档不活跃的账户，但只要你在使用 Shift，你的进度就是安全的。",
      "faq.points-rewards.8.q": "我符合条件，但奖励合作伙伴没有兑现优惠，怎么办？",
      "faq.points-rewards.8.a": "请发邮件到 [info@gogreenstreets.org](mailto:info@gogreenstreets.org)，写明合作伙伴名称、日期和经过。我们会直接与合作伙伴沟通解决，让你享受到优惠。",
      "faq.points-rewards.9.q": "我可以推荐一家商家成为奖励合作伙伴吗？",
      "faq.points-rewards.9.a": "当然可以。如果你希望某家本地商家加入 Shift 网络，请发邮件到 [info@gogreenstreets.org](mailto:info@gogreenstreets.org) 告诉我们。我们一直在扩大这个网络。",
      "faq.badges-streaks-tiers.title": "徽章、连续天数和等级",
      "faq.badges-streaks-tiers.1.q": "有哪些等级？",
      "faq.badges-streaks-tiers.1.a": "Shift 有五个等级：Starter、Mover、Shifter、Pacesetter 和 Trailblazer。通过绿色出行并保持较高的 60 天 Shift Rate 来升级。每升一级，每次出行获得的 XP 更多，所有合作伙伴优惠都在 Mover 解锁。",
      "faq.badges-streaks-tiers.2.q": "什么是 Shift Rate？",
      "faq.badges-streaks-tiers.2.a": "Shift Rate 是你的出行中不开车的比例：步行、骑行、滑板车、公共交通或拼车。主页显示你的 60 天 Shift Rate，也就是决定你等级的那个，所以偶尔一周表现不好也不会让你降级。",
      "faq.badges-streaks-tiers.3.q": "成就徽章是怎么运作的？",
      "faq.badges-streaks-tiers.3.a": "达到特定里程碑就能获得成就徽章：尝试新的出行方式、保持连续天数、达到累计距离目标、完成 Roams 等。“进度”标签会显示你已解锁的徽章和下一个目标。大多数徽章获得时还会奖励额外 XP。",
      "faq.badges-streaks-tiers.4.q": "什么是精选目标？",
      "faq.badges-streaks-tiers.4.a": "精选目标是为期 14 天的冲刺，突出你最接近获得的下一枚徽章。在 14 天内完成目标，除了徽章本身的 XP，还能额外获得 50% 的 XP。",
      "faq.badges-streaks-tiers.5.q": "连续天数是怎么计算的？",
      "faq.badges-streaks-tiers.5.a": "连续天数统计你至少有一次绿色出行（步行、骑行、公共交通或电动滑板车）的天数。你有 2 天的宽限期：最多连续两天没有出行，连续记录依然保留。连续三天没有绿色出行就会重置。刚开始用 Shift？在你的每日连续天数达到 3 天之前，主页会统计你连续有绿色出行的周数。MBTA 服务严重中断期间，我们也会保护你的连续记录；如果你要外出，在 个人资料 > 设置 中开启度假模式，你的连续记录会等你回来。",
      "faq.badges-streaks-tiers.6.q": "连续记录中断了会怎样？",
      "faq.badges-streaks-tiers.6.a": "你当前的连续天数会重置为 1，但你最长的连续记录会保存在个人资料中。连续天数是为了激励你，而不是惩罚你。准备好了，随时开始新的连续记录。",
      "faq.roams.title": "Roams",
      "faq.roams.1.q": "什么是 Roam？",
      "faq.roams.1.a": "Roam 是精心设计的出游路线：沿着步行、骑行、公共交通或多种方式组合的路线设置一组打卡点，你可以按任意顺序前往。可以把它看作一次自助游览，奖励你用绿色出行方式探索你的城市。Roams 有短的街区环线，也有更长的跨城探险。",
      "faq.roams.2.q": "怎么开始一个 Roam？",
      "faq.roams.2.a": "打开“社区”标签，查找可参加的 Roams。点击一个 Roam，可在地图上看到它的打卡点、预计距离和推荐的出行方式（步行、骑行、公共交通或任意组合）。准备好后，点击“开始这个Roam”。你每到一个打卡点，应用都会记录你的进度。",
      "faq.roams.3.q": "打卡点是怎么识别的？",
      "faq.roams.3.a": "你走近打卡点时，应用会通过手机定位自动识别你已到达。如果没有自动识别（在建筑密集的地方 GPS 可能不够精确），你可以在地图上点击打卡点，在附近时使用手动打卡按钮。两种方式效果相同。",
      "faq.roams.4.q": "每个打卡点都要去吗？",
      "faq.roams.4.a": "大多数 Roams 需要去完所有打卡点才算完成。有些步道 Roams 只需要去其中一部分，额外打卡点始终是可选的。Roam 详情页面会显示你需要去几个打卡点。",
      "faq.roams.5.q": "打卡点之间需要按指定路线走吗？",
      "faq.roams.5.a": "不需要。打卡点之间怎么走由你决定。地图会显示打卡点的位置，但怎么到达由你自己选择。步行、骑行或乘坐公共交通都可以，只要在该 Roam 推荐的出行方式之内。",
      "faq.roams.6.q": "完成一个 Roam 能获得什么？",
      "faq.roams.6.a": "完成 Roam 可获得一枚徽章和 XP。有些 Roams 属于合集，完成合集里的所有 Roams 还能获得一枚额外徽章。",
      "faq.roams.7.q": "参加 Roams 有什么安全建议？",
      "faq.roams.7.a": "始终遵守交通规则，使用人行道、自行车道和人行横道。注意周围环境，行进中不要盯着手机。出发前规划好路线，尤其是较长的 Roams。带上水，穿适合天气的装备，长途出行前告诉别人你的计划。应用只是向导，不是 GPS 导航，请自己判断路线是否安全。",
      "faq.competitions.title": "抽奖和挑战",
      "faq.competitions.1.q": "什么是 Walk/Ride Day？",
      "faq.competitions.1.a": "每月有一天，你在 Shift 中记录的每次步行、骑行或公共交通出行，都会让你参加一次奖品抽奖。自动参加，无需报名。面向 18 岁及以上的马萨诸塞州居民，无需购买。[Walk/Ride Day 页面](/programs/walk-ride-days)上有日期和奖品，[正式规则](/events/walk-ride-day/rules)中有详细说明。",
      "faq.competitions.2.q": "还有其他挑战吗？",
      "faq.competitions.2.a": "使用 Shift 的工作单位和团体会举办自己的挑战，如果你是其中一员，就会在应用中看到。尝试新事物也能从 Shift 获得礼品卡，比如用骑行或公共交通完成一段常走的行程。",
      "faq.competitions.3.q": "怎么选出中奖者？中奖后会怎样？",
      "faq.competitions.3.a": "抽奖结束后，从所有符合条件的参与机会中随机抽出中奖者。Shift 记录的出行，或你修正、确认过的出行，都能获得抽奖机会；通过“记录过往出行”添加的出行不能。如果你中奖了，我们会给你发邮件，并在应用中通知你。请在显示的期限内到“奖励”标签领取奖品。",
      "faq.competitions.4.q": "Shift Your Summer 怎么了？",
      "faq.competitions.4.a": "Shift Your Summer 在 2026 年 6 月至 8 月举行，现已结束。它的[正式规则](/events/shift-your-summer/rules)仍可在网上查看。",
      "faq.for-rewards-partners.title": "奖励合作伙伴",
      "faq.for-rewards-partners.1.q": "怎样成为 Shift 奖励合作伙伴？",
      "faq.for-rewards-partners.1.a": "非常欢迎你加入。请访问 [gogreenstreets.org/shift/rewards-partners](/shift/rewards-partners)，或发邮件到 [info@gogreenstreets.org](mailto:info@gogreenstreets.org)。我们会带你完成设置，过程简单，而且参与免费。",
      "faq.for-rewards-partners.2.q": "怎么核实 Shift 兑换？",
      "faq.for-rewards-partners.2.a": "顾客想使用 Shift 优惠时，会在应用屏幕上向你出示他们的等级徽章。看到这个就可以给予优惠，当场无需登录任何后台。你加入时，我们会提供一份可以放在收银台的[一页纸打印指南](/cashier-guide.html)。",
      "faq.for-rewards-partners.3.q": "怎么进入我的商家后台？",
      "faq.for-rewards-partners.3.a": "前往 [gogreenstreets.org/shift/rewards-partners](/shift/rewards-partners)，在“合作伙伴登录”下输入你的电子邮箱。我们会给你发送登录链接。你的后台会显示你的优惠、兑换记录和门店地点。",
      "faq.for-rewards-partners.4.q": "成为奖励合作伙伴要花多少钱？",
      "faq.for-rewards-partners.4.a": "不花钱。加入 Shift 奖励合作伙伴网络没有任何费用。你自己决定提供什么样的奖励，并能接触到一个积极参与、注重可持续发展的本地顾客群体。",
      "faq.for-rewards-partners.5.q": "我可以修改或暂停我的奖励优惠吗？",
      "faq.for-rewards-partners.5.a": "可以。在后台你可以编辑优惠、开启或关闭门店地点，以及暂停你的展示。暂停期间，你的优惠和门店在应用中会被隐藏，直到你重新启用。如需更改适用人群，请发邮件到 info@gogreenstreets.org。",
      "faq.for-schools.title": "学校",
      "faq.for-schools.1.q": "Shift 校园版是怎么运作的？",
      "faq.for-schools.1.a": "Shift 校园版是以班级为单位的绿色出行挑战。每天老师通过简单的举手统计，了解学生是怎么上学的。班级会因步行、骑行和乘坐公共交通获得表彰，还可以在校内和校际之间比赛。这个项目有趣、容易开展，并完全符合 COPPA。不会创建学生账户，也不收集任何个人数据。",
      "faq.for-schools.2.q": "班级代码是怎么用的？",
      "faq.for-schools.2.a": "每个参与的班级都会获得一个独有的 6 位代码。老师用这个代码通过 [Shift 校园版门户](/shift/schools)提交班级的每日统计。代码在项目设置时分配，在整个挑战期间保持不变。",
      "faq.for-schools.3.q": "我是学校协调员，该从哪里开始？",
      "faq.for-schools.3.a": "欢迎！作为学校协调员，你是学校与 Green Streets Initiative 之间的主要联系人。先查看我们在入门培训时分享的项目概览和学校协调员快速入门卡。你的第一步是确认参与的班级、把班级代码发给老师，并分发家长须知。有任何问题，随时联系 [info@gogreenstreets.org](mailto:info@gogreenstreets.org)。",
      "faq.for-schools.4.q": "我是家长，可以怎么帮忙？",
      "faq.for-schools.4.a": "家长作为家长志愿者和步行与骑行巴士领队，发挥着关键作用。步行与骑行巴士是一群家庭沿着固定路线一起步行或骑车上学。如果你有兴趣发起或加入一个，请联系你的学校协调员，或发邮件到 [info@gogreenstreets.org](mailto:info@gogreenstreets.org)。",
      "faq.for-schools.5.q": "学生数据是隐私的吗？",
      "faq.for-schools.5.a": "是的。Shift 校园版从设计上就把学生隐私放在核心。不会创建学生个人账户。数据只按班级收集（例如“今天有 12 名学生步行上学”），从不涉及姓名、位置或任何个人信息。这个项目完全符合 COPPA。",
      "faq.for-schools.6.q": "学生可以使用 Shift 应用吗？",
      "faq.for-schools.6.a": "Shift 应用面向 13 岁及以上的人，部分功能仅限 18 岁及以上的成年人。Shift 校园版的班级挑战是一项独立的、不需要应用的活动：学生通过老师每天的举手统计参与，不需要任何设备或账户。",
      "faq.privacy-data.title": "隐私和数据",
      "faq.privacy-data.1.q": "Shift 会收集哪些数据？",
      "faq.privacy-data.1.a": "你的电子邮箱、名字、你保存的地点，以及你的出行（起点和终点、距离、时间和出行方式）。还有你自己选择添加的内容：学校或工作邮箱、从 Apple Health 或 Health Connect 导入的运动记录，以及参加奖品抽奖时填写的出生日期。如果你使用 AI 助手，你的对话会发送给 Anthropic 的 Claude 来回答你，我们会保存这些对话 12 个月。我们从不出售你的个人数据。详情请参阅我们的[隐私政策](/privacy)。",
      "faq.privacy-data.2.q": "我的位置数据是怎么使用的？",
      "faq.privacy-data.2.a": "位置数据用于识别和记录你的出行：计算距离、判断你的出行方式，并把你的出行计入你所在城镇和团体的排行榜。我们不会与第三方共享原始位置数据。",
      "faq.privacy-data.3.q": "谁能看到我的个人资料？",
      "faq.privacy-data.3.a": "个人资料默认公开，所以 Shift 中的其他人可以看到你的名字、照片和徽章，你也会出现在排行榜上。如果想隐藏，请在 个人资料 > 设置 > 隐私 中关闭“公开个人资料”。无论哪种设置，你的出行都仍会计入你的团体。",
      "faq.privacy-data.4.q": "怎么删除我的账户和数据？",
      "faq.privacy-data.4.a": "前往 个人资料 > 设置 > 账户 > 删除账户。这会永久删除你的个人资料和出行记录。如果遇到任何问题，请发邮件到 [info@gogreenstreets.org](mailto:info@gogreenstreets.org)，我们会帮你处理。",
      "faq.account-settings.title": "账户和设置",
      "faq.account-settings.1.q": "怎么登录？需要密码吗？",
      "faq.account-settings.1.a": "Shift 不使用密码。在登录页面输入你的电子邮箱，我们会给你发送登录链接；请在同一部手机上打开。你也可以用 Google 继续，或在 iPhone 上用 Apple 继续。如果链接无法使用，请重新给自己发一个，并检查垃圾邮件文件夹。",
      "faq.account-settings.2.q": "怎么修改我的名字或社区？",
      "faq.account-settings.2.a": "在 个人资料 > 编辑资料 中可以修改名字和照片。你的社区跟随你的“家”这个地点，可以在 个人资料 > 你的地点 中更改。",
      "faq.account-settings.3.q": "Shift 可以用其他语言吗？",
      "faq.account-settings.3.a": "可以。Shift 支持英语、西班牙语、葡萄牙语和中文。在 个人资料 > 设置 > 语言 中选择。",
      "faq.account-settings.4.q": "怎么更新 Shift 或查看版本？",
      "faq.account-settings.4.a": "大多数更新会在你下次打开 Shift 时自动安装。个人资料 > 帮助 会显示你的版本和最近一次更新时间。较大的更新会通过 App Store 或 Google Play 提供新版本。",
      "faq.account-settings.5.q": "怎么在应用内获取帮助或发送反馈？",
      "faq.account-settings.5.a": "打开 个人资料 > 帮助。点击 **帮助与常见问题** 回到这个页面，或点击 **发送反馈** 给我们发邮件，手机和应用信息会自动填好。你也可以直接发邮件到 [info@gogreenstreets.org](mailto:info@gogreenstreets.org)。",
      "faq.account-settings.6.q": "我遇到的技术问题这里没有列出。",
      "faq.account-settings.6.a": "在 个人资料 > 帮助 中使用 **发送反馈**。它会自动填入你的手机型号、系统和应用版本，以及一份简短的追踪摘要（不含位置），帮助我们快速找到问题。也可以发邮件到 [info@gogreenstreets.org](mailto:info@gogreenstreets.org)，附上问题描述，有截图更好。我们会尽快回复你。",
    },
  },
)
